    function sqToCenter(sq) {
      const file = sq.charCodeAt(0) - 97; // a=0
      const rank = parseInt(sq[1], 10) - 1; // 1=0
      if (file < 0 || file > 7 || rank < 0 || rank > 7 || !sq || sq.length < 2) return null;
      // 与格子渲染一致：files/ranks 数组
      const f = boardFlipped ? (7 - file) : file;
      const r = boardFlipped ? rank : (7 - rank); // 屏幕行：上=0
      return { x: (f + 0.5) * 12.5, y: (r + 0.5) * 12.5 };
    }

    function drawArrows(arrows) {
      // Chess.com 风格：整段填充箭头（杆身 + 箭头一体），不再用简陋三角 marker
      const layer = document.getElementById('arrowLayer');
      if (!layer) return;
      let html = '';
      (arrows || []).forEach((a) => {
        const p1 = sqToCenter(a.from);
        const p2 = sqToCenter(a.to);
        if (!p1 || !p2) return;
        const dx = p2.x - p1.x, dy = p2.y - p1.y;
        const len = Math.sqrt(dx * dx + dy * dy) || 1;
        if (len < 2) return;
        const ux = dx / len, uy = dy / len;
        const px = -uy, py = ux; // 垂直方向

        // 起终点内缩，避免盖住棋子中心
        const insetStart = Math.min(4.2, len * 0.28);
        const insetEnd = Math.min(3.6, len * 0.22);
        const x0 = p1.x + ux * insetStart;
        const y0 = p1.y + uy * insetStart;
        const x3 = p2.x - ux * insetEnd;
        const y3 = p2.y - uy * insetEnd;
        const shaftLen = Math.max(0.5, Math.sqrt((x3 - x0) * (x3 - x0) + (y3 - y0) * (y3 - y0)));

        // 杆宽 / 箭头尺寸（viewBox 0–100，一格约 12.5）
        const baseW = (a.width != null ? a.width : 2.6);
        const half = Math.max(1.15, Math.min(2.1, baseW * 0.55));
        const headLen = Math.min(5.8, Math.max(4.2, shaftLen * 0.32));
        const headHalf = half * 2.15;
        const shaftEnd = Math.max(0.3, shaftLen - headLen * 0.88);

        const sx = x0 + ux * shaftEnd;
        const sy = y0 + uy * shaftEnd;

        // 多边形：起点两侧 → 箭头根部两侧 → 箭头两翼 → 尖端
        const pts = [
          [x0 + px * half, y0 + py * half],
          [sx + px * half, sy + py * half],
          [sx + px * headHalf, sy + py * headHalf],
          [x3, y3],
          [sx - px * headHalf, sy - py * headHalf],
          [sx - px * half, sy - py * half],
          [x0 - px * half, y0 - py * half]
        ];
        const d = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(2) + ',' + p[1].toFixed(2)).join(' ') + ' Z';
        const c = a.color || '#5c8a3e';
        const op = a.opacity == null ? 0.72 : a.opacity;
        html += '<path d="' + d + '" fill="' + c + '" fill-opacity="' + op +
          '" stroke="' + c + '" stroke-opacity="' + (op * 0.9) +
          '" stroke-width="0.35" stroke-linejoin="round"/>';
      });
      layer.innerHTML = html;
    }

    function clearArrows() {
      drawArrows([]);
      const hint = document.getElementById('arrowHint');
      if (hint) hint.textContent = '';
    }

    function uciToFromTo(uci) {
      if (!uci || uci.length < 4) return null;
      return { from: uci.slice(0, 2), to: uci.slice(2, 4), promo: uci[4] || '' };
    }

    // 仅当 uci 在当前 FEN 下合法才返回 from/to（绝不回退到非法坐标）
    function legalUciOnFen(fen, uci) {
      const ft = uciToFromTo(uci);
      if (!ft) return null;
      try {
        const t = new (getChessCtor())(fen);
        const m = t.move({ from: ft.from, to: ft.to, promotion: ft.promo || 'q' });
        if (!m) return null;
        return { from: m.from, to: m.to, san: m.san, uci: m.from + m.to + (m.promotion || '') };
      } catch (_) {
        return null;
      }
    }

    // 实时评估箭头（点「重新评估」后显示，无需先生成角标）
    let liveEvalArrowState = null; // { bestUci, altUcis:[], threatUcis:[], fen: '' }

    function pieceValue(ch) {
      const m = { p:1, n:3, b:3, r:5, q:9, k:0, P:1, N:3, B:3, R:5, Q:9, K:0 };
      return m[ch] || 0;
    }

    function pieceTypeValue(type) {
      const m = { p:1, n:3, b:3, r:5, q:9, k:99 };
      return m[type] || 0;
    }

    /** 粗略静态兑换：目标格被对方再吃时的净值（越大越赚） */
    function roughCaptureNet(chess, move) {
      const cap = move.captured ? pieceTypeValue(move.captured) : 0;
      const atk = pieceTypeValue(move.piece);
      if (!cap && !(move.flags && move.flags.indexOf('e') >= 0)) return -99;
      // 走后该子是否被对方更低/等价值子可吃
      try {
        const t = new (getChessCtor())(chess.fen());
        t.move({ from: move.from, to: move.to, promotion: move.promotion || 'q' });
        const replies = t.moves({ verbose: true });
        let minRecap = 99;
        for (const r of replies) {
          if (r.to === move.to && r.captured) {
            minRecap = Math.min(minRecap, pieceTypeValue(r.piece));
          }
        }
        if (minRecap < 99) {
          // 被吃回：净分 = 吃掉的 - 自己被吃的棋子价值
          return cap - atk;
        }
        return cap; // 白吃
      } catch (_) {
        return cap - atk;
      }
    }

    /**
     * 红箭威胁：只标「有棋理」的战术
     * - 净赚或等价的吃子（SEE 粗算 >= 0）
     * - 将军，且将军子不被更低价值子白吃（或将死）
     * - 不标送子式亏本吃 / 自杀将军
     */
    function computeAttackThreatUcis(chess, maxN) {
      maxN = maxN || 3;
      const out = [];
      try {
        const moves = chess.moves({ verbose: true });
        const scored = [];
        for (const m of moves) {
          let score = 0;
          const isCap = m.flags && (m.flags.indexOf('c') >= 0 || m.flags.indexOf('e') >= 0);
          if (isCap) {
            const net = roughCaptureNet(chess, m);
            if (net < 0) {
              // 亏本兑换：通常不标，除非吃后形成将死
            } else {
              score += 30 + net * 12;
            }
          }
          let givesCheck = false;
          let isMate = false;
          try {
            const t = new (getChessCtor())(chess.fen());
            t.move({ from: m.from, to: m.to, promotion: m.promotion || 'q' });
            if (typeof t.in_checkmate === 'function' && t.in_checkmate()) isMate = true;
            else if (typeof t.isCheckmate === 'function' && t.isCheckmate()) isMate = true;
            if (typeof t.in_check === 'function' && t.in_check()) givesCheck = true;
            else if (typeof t.isCheck === 'function' && t.isCheck()) givesCheck = true;

            if (isMate) {
              score += 200;
            } else if (givesCheck) {
              // 将军子是否被白吃（对方能用更低价值子吃到落点）
              const replies = t.moves({ verbose: true });
              let hangingToCheaper = false;
              const myVal = pieceTypeValue(m.piece);
              for (const r of replies) {
                if (r.to === m.to && r.captured) {
                  if (pieceTypeValue(r.piece) < myVal || pieceTypeValue(r.piece) <= 3 && myVal >= 5) {
                    hangingToCheaper = true;
                    break;
                  }
                  // 被等价值吃回也算勉强，降分
                  if (pieceTypeValue(r.piece) <= myVal) {
                    score -= 8;
                  }
                }
              }
              if (hangingToCheaper && !isCap) {
                // 纯自杀将军：丢
                score = Math.min(score, 0);
              } else {
                score += 22;
              }
            }
          } catch (_) {}

          if (score > 0) {
            scored.push({
              uci: m.from + m.to + (m.promotion || ''),
              score: score,
              san: m.san
            });
          }
        }
        scored.sort((a, b) => b.score - a.score);
        // 去重落点：同一目标只留最高分（避免箭头乱）
        const seenTo = new Set();
        for (const s of scored) {
          const to = s.uci.slice(2, 4);
          if (seenTo.has(to)) continue;
          seenTo.add(to);
          out.push(s.uci);
          if (out.length >= maxN) break;
        }
      } catch (_) {}
      return out;
    }

    function setLiveEvalArrows(bestUci, altUcis) {
      if (!analysisChess) {
        liveEvalArrowState = null;
        return;
      }
      const fen = analysisChess.fen();
      // 只保留当前局面下合法的引擎着法（仅绿/蓝箭，无红箭）
      let best = '';
      if (bestUci && legalUciOnFen(fen, bestUci)) best = bestUci;
      const best4 = best.slice(0, 4);
      const alts = [];
      for (const u of (altUcis || [])) {
        if (!u || u.slice(0, 4) === best4) continue;
        if (!legalUciOnFen(fen, u)) continue;
        alts.push(u);
        if (alts.length >= 2) break;
      }
      liveEvalArrowState = {
        bestUci: best,
        altUcis: alts,
        threatUcis: [],
        fen: fen
      };
      updateThreatArrows();
    }

    function clearLiveEvalArrows() {
      liveEvalArrowState = null;
    }

    function updateThreatArrows() {
      const hint = document.getElementById('arrowHint');
      const arrows = [];
      let hintText = '';
      // 演示「为什么是? / ??」期间由演示逻辑自行画箭头，避免被覆盖
      if (typeof whyDemoRunning !== 'undefined' && whyDemoRunning) {
        return;
      }
      if (!analysisChess) {
        drawArrows([]);
        if (hint) hint.textContent = '';
        return;
      }
      const fenNow = analysisChess.fen();

      // 1) 实时评估：仅绿色最佳着 + 蓝色备选（无红箭）
      if (liveEvalArrowState && liveEvalArrowState.fen === fenNow &&
          (liveEvalArrowState.bestUci || (liveEvalArrowState.altUcis || []).length)) {
        const st = liveEvalArrowState;
        if (st.bestUci) {
          const legB = legalUciOnFen(fenNow, st.bestUci);
          if (legB) {
            arrows.push({ from: legB.from, to: legB.to, color: '#15781b', opacity: 0.78, width: 2.9 });
            hintText = '最佳着：' + (legB.san || st.bestUci);
          }
        }
        (st.altUcis || []).forEach((u) => {
          const leg = legalUciOnFen(fenNow, u);
          if (leg) arrows.push({ from: leg.from, to: leg.to, color: '#1b4f9c', opacity: 0.55, width: 2.15 });
        });
        if (!arrows.length) hintText = '点「重新评估」刷新箭头';
        drawArrows(arrows);
        if (hint) hint.textContent = hintText;
        return;
      }
      if (liveEvalArrowState && liveEvalArrowState.fen && liveEvalArrowState.fen !== fenNow) {
        liveEvalArrowState = null;
      }

      // 2) 角标：只在「走之前」画本手更佳着（绿箭）
      if (!exploreMode && analysisPly >= 0 && analysisPly < analysisMoves.length && moveAnnotations[analysisPly]) {
        const ann = moveAnnotations[analysisPly];
        if (ann && ann.bestUci) {
          const legB = legalUciOnFen(fenNow, ann.bestUci);
          if (legB) {
            const bad = ['inaccuracy', 'mistake', 'blunder', 'miss'].includes(ann.kind);
            arrows.push({ from: legB.from, to: legB.to, color: '#15781b', opacity: 0.8, width: 2.8 });
            if (bad) {
              hintText = '此步更好：' + (ann.bestSan || legB.san || ann.bestUci) +
                '（你走了 ' + analysisMoves[analysisPly].san + '）';
            } else {
              hintText = '引擎参考：' + (ann.bestSan || legB.san || ann.bestUci);
            }
          }
        }
      } else if (!exploreMode && analysisPly > 0 && moveAnnotations[analysisPly - 1]) {
        const ann = moveAnnotations[analysisPly - 1];
        const bad = ann && ['inaccuracy', 'mistake', 'blunder', 'miss'].includes(ann.kind);
        if (bad) {
          const bestHint = ann.bestSan || ann.bestUci || '';
          hintText = bestHint
            ? ('上一步有问题 · 本应走：' + bestHint + '（点「上一步」看绿箭）')
            : '上一步有问题（点「上一步」查看）';
        }
      } else if (exploreMode) {
        hintText = '对局浏览器 · 点「重新评估」显示最佳着（绿）';
      } else if (!moveAnnotations.length) {
        hintText = '点棋走子可探索变例；点「重新评估」显示最佳着（绿）';
      }

      drawArrows(arrows);
      if (hint) hint.textContent = hintText;
    }

    function renderCoords() {
      const ranksEl = document.getElementById('boardRanks');
      const filesEl = document.getElementById('boardFiles');
      if (!ranksEl || !filesEl) return;
      const rankOrder = boardFlipped ? [1,2,3,4,5,6,7,8] : [8,7,6,5,4,3,2,1];
      const fileOrder = boardFlipped ? 'hgfedcba' : 'abcdefgh';
      ranksEl.innerHTML = rankOrder.map(n => '<span>' + n + '</span>').join('');
      filesEl.innerHTML = fileOrder.split('').map(c => '<span>' + c + '</span>').join('');
    }

    function syncExploreUi() {
      const ban = document.getElementById('exploreBanner');
      const btn = document.getElementById('btnExitExplore');
      if (ban) ban.classList.toggle('on', !!exploreMode);
      if (btn) btn.style.display = exploreMode ? '' : 'none';
    }

    function exitExploreMode(keepPly) {
      exploreMode = false;
      exploreMoves = [];
      exploreBasePly = 0;
      analysisSelectedSq = null;
      syncExploreUi();
      if (keepPly != null) gotoPly(keepPly);
    }

    function getAnalysisLegalTargets(fromSq) {
      if (!analysisChess || !fromSq) return [];
      try {
        return analysisChess.moves({ square: fromSq, verbose: true }) || [];
      } catch (_) { return []; }
    }

    function renderBoard(chess, lastMove) {
      renderCoords();
      const board = document.getElementById('board');
      const fen = chess.fen().split(' ')[0];
      const rows = fen.split('/');
      let html = '';
      const files = boardFlipped ? [7,6,5,4,3,2,1,0] : [0,1,2,3,4,5,6,7];
      const ranks = boardFlipped ? [0,1,2,3,4,5,6,7] : [7,6,5,4,3,2,1,0];
      const legalFrom = analysisSelectedSq ? getAnalysisLegalTargets(analysisSelectedSq) : [];
      const legalTo = new Set(legalFrom.map(m => m.to));
      const captureTo = new Set(legalFrom.filter(m => m.captured || (m.flags && (m.flags.indexOf('c') >= 0 || m.flags.indexOf('e') >= 0))).map(m => m.to));
      for (const r of ranks) {
        let row = rows[7 - r].replace(/\d/g, d => ' '.repeat(+d));
        for (const f of files) {
          const isLight = (r + f) % 2 === 1;
          const sq = 'abcdefgh'[f] + (r + 1);
          let cls = 'sq ' + (isLight ? 'light' : 'dark');
          if (lastMove) {
            if (sq === lastMove.from) cls += ' last-from';
            if (sq === lastMove.to) cls += ' last-to';
          }
          if (analysisSelectedSq && sq === analysisSelectedSq) cls += ' selected';
          if (analysisSelectedSq && legalTo.has(sq)) {
            cls += captureTo.has(sq) ? ' legal-capture' : ' legal-target';
          }
          const ch = row[f];
          let piece = '';
          if (ch && ch !== ' ') {
            const color = ch === ch.toUpperCase() ? 'w' : 'b';
            const key = color + ch.toUpperCase();
            piece = PIECE_SVG[key] || '';
          }
          let corner = '';
          if (!exploreMode && lastMove && sq === lastMove.to && analysisPly > 0 && moveAnnotations[analysisPly - 1]) {
            const kind = moveAnnotations[analysisPly - 1].kind;
            const meta = GLYPH_META[kind];
            if (meta) {
              corner = '<div class="board-glyph ' + meta.cls + '" title="' + meta.title + '">' + meta.text + '</div>';
            }
          }
          html += '<div class="' + cls + '" data-sq="' + sq + '">' + piece + corner + '</div>';
        }
      }
      board.innerHTML = html;
      updateThreatArrows();
      syncExploreUi();
    }

    function getChessCtor() {
      if (typeof Chess === 'function') return Chess;
      if (typeof window !== 'undefined' && typeof window.Chess === 'function') return window.Chess;
      throw new Error('棋盘库未就绪（请重新下载最新 HTML）');
    }
    function ensureChess() {
      getChessCtor();
    }

    function parseMovesFromGame(g) {
      ensureChess();
      const chess = new (getChessCtor())();
      let moves = [];
      // 1) full PGN
      if (g.pgn && g.pgn.length > 20) {
        try {
          const ok = chess.load_pgn(g.pgn, { sloppy: true });
          if (ok) {
            moves = chess.history({ verbose: true });
            chess.reset();
            return { chess, moves };
          }
        } catch (e) { console.warn('pgn parse fail', e); }
      }
      // 2) space-separated SAN / UCI moves string (Lichess)
      if (g.moves && g.moves.trim()) {
        chess.reset();
        moves = [];
        const parts = g.moves.trim().split(/\s+/);
        for (const m of parts) {
          try {
            // try SAN first, then UCI
            let moved = null;
            try { moved = chess.move(m, { sloppy: true }); } catch (_) {}
            if (!moved && m.length >= 4) {
              moved = chess.move({
                from: m.slice(0, 2),
                to: m.slice(2, 4),
                promotion: m[4] || 'q'
              });
            }
            if (moved) moves.push(moved);
            else break;
          } catch (_) { break; }
        }
        chess.reset();
        return { chess, moves };
      }
      chess.reset();
      return { chess, moves: [] };
    }

    function gotoPly(ply) {
      if (!analysisChess) return;
      // 离开探索模式回到主线
      exploreMode = false;
      exploreMoves = [];
      exploreBasePly = 0;
      analysisSelectedSq = null;
      analysisPly = Math.max(0, Math.min(ply, analysisMoves.length));
      analysisChess.reset();
      let last = null;
      for (let i = 0; i < analysisPly; i++) {
        last = analysisChess.move(analysisMoves[i]);
      }
      clearLiveEvalArrows();
      renderBoard(analysisChess, last);
      document.querySelectorAll('#moveList span[data-ply]').forEach(el => {
        el.classList.toggle('active', parseInt(el.dataset.ply, 10) === analysisPly);
      });
      // 不在走子时自动评估，避免打断「生成角标」；需评估时点「重新评估」
      if (!annotating) {
        document.getElementById('engineStatus').textContent =
          moveAnnotations.length ? '可点「重新评估」看当前局面' : '点「生成角标」为整局打分，或「重新评估」看当前局面';
      }
      if (typeof updateWhyGlyphButton === 'function' && !whyDemoRunning) updateWhyGlyphButton();
    }



    function buildMoveList() {
      let html = '';
      for (let i = 0; i < analysisMoves.length; i++) {
        if (i % 2 === 0) html += '<span style="opacity:.5">' + (Math.floor(i / 2) + 1) + '.</span> ';
        const ann = moveAnnotations[i];
        let detail = '';
        if (ann && ann.cpl != null) detail = '落后最佳 ' + Math.round(ann.cpl) + 'cp';
        if (ann && ann.wasBest) detail = '引擎最佳着';
        const g = ann ? glyphHtml(ann.kind, detail) : '';
        const cls = ann ? ' has-glyph' : '';
        html += '<span class="' + cls.trim() + '" data-ply="' + (i + 1) + '" onclick="gotoPly(' + (i + 1) + ')">' + analysisMoves[i].san + g + '</span> ';
      }
      document.getElementById('moveList').innerHTML = html || '无着法数据（仍可看初始局面）';
      if (typeof updateWhyGlyphButton === 'function' && !whyDemoRunning) updateWhyGlyphButton();
    }


    // ---- 为什么是 ? / ?? ：自动演示 ----
    let whyDemoRunning = false;
    let whyDemoTimers = [];

    function clearWhyDemoTimers() {
      whyDemoTimers.forEach(t => clearTimeout(t));
      whyDemoTimers = [];
    }

    function stopWhyDemo(restorePly) {
      clearWhyDemoTimers();
      whyDemoRunning = false;
      const btn = document.getElementById('btnWhyGlyph');
      if (btn) btn.disabled = false;
      if (typeof restorePly === 'number' && analysisChess) {
        exploreMode = false;
        exploreMoves = [];
        analysisSelectedSq = null;
        gotoPly(restorePly);
      }
      updateWhyGlyphButton();
    }

    /** 当前相关的问题着：优先「刚走完的一手」，否则「即将走的一手」 */
    function getActiveProblemAnnotation() {
      if (!moveAnnotations || !moveAnnotations.length) return null;
      const badKinds = { blunder: 1, mistake: 1, miss: 1 };
      if (analysisPly > 0 && moveAnnotations[analysisPly - 1]) {
        const ann = moveAnnotations[analysisPly - 1];
        if (ann && badKinds[ann.kind]) {
          return { ply: analysisPly - 1, ann: ann, viewAfter: true };
        }
      }
      if (analysisPly >= 0 && analysisPly < analysisMoves.length && moveAnnotations[analysisPly]) {
        const ann = moveAnnotations[analysisPly];
        if (ann && badKinds[ann.kind]) {
          return { ply: analysisPly, ann: ann, viewAfter: false };
        }
      }
      return null;
    }

    function updateWhyGlyphButton() {
      const btn = document.getElementById('btnWhyGlyph');
      if (!btn) return;
      if (whyDemoRunning || exploreMode) {
        btn.style.display = 'none';
        return;
      }
      const info = getActiveProblemAnnotation();
      if (!info) {
        btn.style.display = 'none';
        return;
      }
      const isBlunder = info.ann.kind === 'blunder' || info.ann.kind === 'miss';
      btn.textContent = isBlunder ? '为什么是双问号？' : '为什么是问号？';
      btn.style.display = '';
      btn.disabled = false;
    }

    function whySleep(ms) {
      return new Promise(resolve => {
        const t = setTimeout(resolve, ms);
        whyDemoTimers.push(t);
      });
    }

    function setAnalysisPositionToPly(ply) {
      analysisPly = Math.max(0, Math.min(ply, analysisMoves.length));
      analysisChess.reset();
      let last = null;
      for (let i = 0; i < analysisPly; i++) {
        last = analysisChess.move(analysisMoves[i]);
      }
      clearLiveEvalArrows();
      renderBoard(analysisChess, last);
      document.querySelectorAll('#moveList span[data-ply]').forEach(el => {
        el.classList.toggle('active', parseInt(el.dataset.ply, 10) === analysisPly);
      });
      return last;
    }

    function playUciOnAnalysis(uci) {
      if (!uci || uci.length < 4 || !analysisChess) return null;
      try {
        const m = analysisChess.move({
          from: uci.slice(0, 2),
          to: uci.slice(2, 4),
          promotion: uci[4] || 'q'
        });
        if (!m) return null;
        analysisPly = analysisPly + 1; // 仅用于演示视觉，主线会恢复
        renderBoard(analysisChess, m);
        return m;
      } catch (_) {
        return null;
      }
    }

    /** 取当前局面下一段引擎主变 UCI 列表（用于向前演示） */
    async function fetchWhyContinuationUcis(fen, maxMoves) {
      maxMoves = maxMoves || 6;
      const out = [];
      try {
        const url = 'https://lichess.org/api/cloud-eval?fen=' + encodeURIComponent(fen) + '&multiPv=1';
        const res = await fetch(url);
        if (res.ok) {
          const data = await res.json();
          const moves = (data && data.pvs && data.pvs[0] && data.pvs[0].moves) || '';
          String(moves).trim().split(/\s+/).filter(Boolean).slice(0, maxMoves).forEach(u => out.push(u));
          if (out.length) return out;
        }
      } catch (_) {}
      // 本地引擎短搜
      try {
        await ensureEngineWorker('stockfish');
        const worker = window.__sfWorker || null;
      } catch (_) {}
      try {
        if (typeof startLocalEngine === 'function' && annEngine) {
          // 用标注引擎做一次短评估
          const r = await new Promise((resolve) => {
            if (!annEngine) return resolve(null);
            const pvs = {};
            let done = false;
            const onMsg = (e) => {
              const line = String(e.data || '');
              if (line.indexOf('info') === 0 && line.indexOf(' pv ') >= 0) {
                const m = line.match(/\bpv ((?:[a-h][1-8][a-h][1-8][qrbn]?[\s]*)+)/);
                const mpv = line.match(/\bmultipv (\d+)/);
                const idx = mpv ? parseInt(mpv[1], 10) : 1;
                if (m) pvs[idx] = m[1].trim().split(/\s+/);
              }
              if (line.indexOf('bestmove') === 0) {
                if (done) return;
                done = true;
                annEngine.removeEventListener('message', onMsg);
                const best = (line.match(/bestmove\s+(\S+)/) || [])[1] || '';
                const list = pvs[1] || (best ? [best] : []);
                resolve(list);
              }
            };
            annEngine.addEventListener('message', onMsg);
            annEngine.postMessage('stop');
            annEngine.postMessage('ucinewgame');
            annEngine.postMessage('position fen ' + fen);
            annEngine.postMessage('go depth 10');
            setTimeout(() => {
              if (done) return;
              done = true;
              try { annEngine.removeEventListener('message', onMsg); } catch (_) {}
              resolve(pvs[1] || []);
            }, 4000);
          });
          if (r && r.length) return r.slice(0, maxMoves);
        }
      } catch (_) {}
      return out;
    }

    async function runWhyGlyphDemo() {
      if (whyDemoRunning || !analysisChess) return;
      const info = getActiveProblemAnnotation();
      if (!info) return;

      const restorePly = analysisPly;
      const ann = info.ann;
      const problemPly = info.ply; // 0-based：问题着本身
      const played = analysisMoves[problemPly];
      if (!played) return;

      const isBlunder = ann.kind === 'blunder' || ann.kind === 'miss';
      const label = isBlunder ? '双问号 ??' : '问号 ?';
      const hint = document.getElementById('arrowHint');
      const btn = document.getElementById('btnWhyGlyph');
      if (btn) btn.disabled = true;
      whyDemoRunning = true;
      clearWhyDemoTimers();
      exploreMode = false;
      exploreMoves = [];
      analysisSelectedSq = null;

      try {
        // 始终从「问题着已经走出」的局面开始向前演示（不回溯）
        const startPly = problemPly + 1;
        setAnalysisPositionToPly(startPly);
        if (hint) {
          hint.textContent = '演示「' + label + '」：你走了 ' + played.san +
            (ann.bestSan ? '（更优是 ' + ann.bestSan + '）' : '') + ' · 看对方如何利用…';
        }

        // 收集向前着法：优先角标里的 reply，再接引擎主变
        const uciQueue = [];
        if (ann.replyUci && legalUciOnFen(analysisChess.fen(), ann.replyUci)) {
          uciQueue.push(ann.replyUci);
        }

        // 预览第一手箭头
        if (uciQueue[0]) {
          const leg0 = legalUciOnFen(analysisChess.fen(), uciQueue[0]);
          if (leg0) {
            drawArrows([{ from: leg0.from, to: leg0.to, color: '#c41e3a', opacity: 0.85, width: 2.8 }]);
          }
        } else if (hint) {
          hint.textContent = '正在计算对方后续着法…';
        }

        // 补全后续主变（从当前局面或走出 reply 后的局面）
        let contFen = analysisChess.fen();
        if (uciQueue[0]) {
          try {
            const t = new (getChessCtor())(contFen);
            t.move({ from: uciQueue[0].slice(0,2), to: uciQueue[0].slice(2,4), promotion: uciQueue[0][4] || 'q' });
            contFen = t.fen();
          } catch (_) {}
        }
        // contFen 已是「reply 之后」或「问题着之后」：主变整段接上即可
        const extra = await fetchWhyContinuationUcis(contFen, 5);
        for (const u of extra) {
          if (!u || u.length < 4) continue;
          // 避免与已入队的着法重复
          if (uciQueue.some(x => x.slice(0, 4) === u.slice(0, 4) && x === u)) continue;
          uciQueue.push(u);
          if (uciQueue.length >= 6) break;
        }

        // 若完全没有后续：尝试直接对「问题着之后」局面取主变
        if (!uciQueue.length) {
          const direct = await fetchWhyContinuationUcis(analysisChess.fen(), 6);
          direct.forEach(u => { if (u && u.length >= 4) uciQueue.push(u); });
        }

        if (!uciQueue.length) {
          if (hint) {
            hint.textContent = label + '：引擎暂未给出可演示的后续着法。更优着是 ' +
              (ann.bestSan || ann.bestUci || '（无）');
          }
          await whySleep(2000);
          if (!whyDemoRunning) return;
          stopWhyDemo(restorePly);
          return;
        }

        // 逐手向前走，间隔 2 秒
        for (let i = 0; i < uciQueue.length; i++) {
          if (!whyDemoRunning) return;
          const u = uciQueue[i];
          // 先画将要走的箭头
          const leg = legalUciOnFen(analysisChess.fen(), u);
          if (leg) {
            drawArrows([{ from: leg.from, to: leg.to, color: i === 0 ? '#c41e3a' : '#15781b', opacity: 0.85, width: 2.8 }]);
            if (hint) {
              const who = (analysisChess.turn() === 'w') ? '白' : '黑';
              hint.textContent = (i === 0 ? '对方利用：' : ('后续 ' + (i + 1) + '：')) +
                who + ' 走 ' + (leg.san || u);
            }
          }
          await whySleep(800); // 短暂停顿让用户看清箭头
          if (!whyDemoRunning) return;
          const moved = playUciOnAnalysis(u);
          if (!moved) break;
          if (hint) {
            hint.textContent = (i === 0
              ? ('对方走了 ' + moved.san + ' · 这就是' + label + '的代价')
              : ('继续：' + moved.san));
          }
          await whySleep(2000);
        }

        if (hint) hint.textContent = '演示结束，已返回主线';
        await whySleep(600);
        stopWhyDemo(restorePly);
      } catch (e) {
        console.warn('why demo failed', e);
        stopWhyDemo(restorePly);
      }
    }

    window.openAnalysis = async function(idx) {
      try {
        document.getElementById('engineStatus').textContent = '加载棋盘库…';
        await ensureChessLib();
        ensureChess();
        const g = storedGames[idx];
        if (!g) {
          alert('对局数据不存在，请重新分析');
          return;
        }
        analysisGame = g;
        boardFlipped = !g.isWhite;
        const parsed = parseMovesFromGame(g);
        analysisChess = parsed.chess;
        analysisMoves = parsed.moves;
        analysisPly = 0;
        exploreMode = false;
        exploreMoves = [];
        exploreBasePly = 0;
        analysisSelectedSq = null;

        const resTxt = g.result === 'win' ? ' · 胜' : g.result === 'loss' ? ' · 负' : g.result === 'draw' ? ' · 和' : '';
        document.getElementById('modalTitle').textContent =
          (g.isWhite ? '白' : '黑') + ' 对 ' + g.opponent + ' · ' + g.opening.zh + resTxt;
        document.getElementById('modal').classList.remove('hidden');
        document.getElementById('engineLines').innerHTML = '';
        document.getElementById('evalBar').style.width = '50%';
        document.getElementById('evalScore').textContent = '—';
        document.getElementById('engineStatus').textContent = '就绪：点「生成角标」开始整局打分（完成前请等待）';
        moveAnnotations = [];
        document.getElementById('reviewSummary')?.classList.add('hidden');
        if (annotateAbort) { try { annotateAbort.abort(); } catch (_) {} }
        const ab = document.getElementById('btnAnnotate');
        if (ab) ab.disabled = false;
        buildMoveList();
        gotoPly(0);
      } catch (err) {
        console.error(err);
        const msg = (err && err.message) ? err.message : String(err);
        alert('打开分析失败：' + msg + '\n\n若持续失败，请用 Chrome/Edge 打开，并确保用的是最新下载的 HTML。');
      }
    };

    document.getElementById('modalClose').onclick = () => {
      if (whyDemoRunning) stopWhyDemo(null);
      document.getElementById('modal').classList.add('hidden');
    };
    document.getElementById('btnStart').onclick = () => {
      if (exploreMode) exitExploreMode(0);
      else gotoPly(0);
    };
    document.getElementById('btnPrev').onclick = () => {
      if (exploreMode && exploreMoves.length) undoExploreMove();
      else gotoPly(analysisPly - 1);
    };
    document.getElementById('btnNext').onclick = () => {
      if (exploreMode) return;
      gotoPly(analysisPly + 1);
    };
    document.getElementById('btnEnd').onclick = () => {
      if (exploreMode) exitExploreMode(analysisMoves.length);
      else gotoPly(analysisMoves.length);
    };
    document.getElementById('btnEngine').onclick = () => requestEval(false);
    document.getElementById('btnAnnotate').onclick = () => annotateGame();
    document.getElementById('btnWhyGlyph')?.addEventListener('click', () => { runWhyGlyphDemo(); });

    document.addEventListener('keydown', e => {
      if (document.getElementById('modal').classList.contains('hidden')) return;
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        if (exploreMode && exploreMoves.length) {
          undoExploreMove();
        } else {
          gotoPly(analysisPly - 1);
        }
      }
      if (e.key === 'ArrowRight') {
        e.preventDefault();
        if (exploreMode) return; // 探索中不沿主线前进
        gotoPly(analysisPly + 1);
      }
      if (e.key === 'Escape') {
        if (exploreMode) {
          e.preventDefault();
          exitExploreMode(exploreBasePly);
        } else {
          document.getElementById('modalClose').click();
        }
      }
    });

    function analysisSqFromEvent(ev) {
      const board = document.getElementById('board');
      if (!board || !analysisChess) return null;
      const t = ev.target && ev.target.closest ? ev.target.closest('.sq[data-sq]') : null;
      if (t && t.getAttribute('data-sq')) return t.getAttribute('data-sq');
      const rect = board.getBoundingClientRect();
      const x = (ev.clientX - rect.left) / rect.width;
      const y = (ev.clientY - rect.top) / rect.height;
      if (x < 0 || y < 0 || x > 1 || y > 1) return null;
      let file = Math.min(7, Math.max(0, Math.floor(x * 8)));
      let rankFromTop = Math.min(7, Math.max(0, Math.floor(y * 8)));
      if (boardFlipped) {
        file = 7 - file;
        rankFromTop = 7 - rankFromTop;
      }
      // 未翻转：顶部为第 8 行
      const rankNum = 8 - rankFromTop;
      return 'abcdefgh'[file] + rankNum;
    }

    function rebuildExplorePosition() {
      if (!analysisChess) return null;
      analysisChess.reset();
      let last = null;
      for (let i = 0; i < exploreBasePly; i++) {
        last = analysisChess.move(analysisMoves[i]);
      }
      for (const m of exploreMoves) {
        last = analysisChess.move({ from: m.from, to: m.to, promotion: m.promotion || 'q' }) || last;
      }
      return last;
    }

    function undoExploreMove() {
      if (!exploreMode || !exploreMoves.length) {
        exitExploreMode(exploreBasePly);
        return;
      }
      exploreMoves.pop();
      analysisSelectedSq = null;
      if (!exploreMoves.length) {
        exitExploreMode(exploreBasePly);
        return;
      }
      const last = rebuildExplorePosition();
      clearLiveEvalArrows();
      renderBoard(analysisChess, last);
      // 自动评估当前探索局面
      try { requestEval(false); } catch (_) {}
    }

    function enterExploreWithMove(moved) {
      if (!moved) return;
      if (!exploreMode) {
        exploreMode = true;
        exploreBasePly = analysisPly;
        exploreMoves = [];
      }
      exploreMoves.push(moved);
      analysisSelectedSq = null;
      clearLiveEvalArrows();
      renderBoard(analysisChess, moved);
      const hint = document.getElementById('arrowHint');
      if (hint) hint.textContent = '探索：' + moved.san + ' · 正在评估最佳着…';
      try { requestEval(false); } catch (_) {}
    }

    function onAnalysisBoardClick(ev) {
      if (!analysisChess) return;
      if (typeof whyDemoRunning !== 'undefined' && whyDemoRunning) return;
      if (document.getElementById('modal').classList.contains('hidden')) return;
      const sq = analysisSqFromEvent(ev);
      if (!sq) return;

      // 选子
      if (!analysisSelectedSq) {
        const piece = analysisChess.get(sq);
        if (!piece || piece.color !== analysisChess.turn()) return;
        analysisSelectedSq = sq;
        const last = analysisChess.history({ verbose: true }).slice(-1)[0] || null;
        // 用当前盘面最后一步高亮
        let lastMove = null;
        if (exploreMode && exploreMoves.length) lastMove = exploreMoves[exploreMoves.length - 1];
        else if (analysisPly > 0 && analysisMoves[analysisPly - 1]) lastMove = analysisMoves[analysisPly - 1];
        renderBoard(analysisChess, lastMove);
        return;
      }

      const from = analysisSelectedSq;
      // 再点同一格：取消选择
      if (sq === from) {
        analysisSelectedSq = null;
        let lastMove = null;
        if (exploreMode && exploreMoves.length) lastMove = exploreMoves[exploreMoves.length - 1];
        else if (analysisPly > 0 && analysisMoves[analysisPly - 1]) lastMove = analysisMoves[analysisPly - 1];
        renderBoard(analysisChess, lastMove);
        return;
      }

      // 点另一己方棋子：改选
      const piece2 = analysisChess.get(sq);
      if (piece2 && piece2.color === analysisChess.turn()) {
        analysisSelectedSq = sq;
        let lastMove = null;
        if (exploreMode && exploreMoves.length) lastMove = exploreMoves[exploreMoves.length - 1];
        else if (analysisPly > 0 && analysisMoves[analysisPly - 1]) lastMove = analysisMoves[analysisPly - 1];
        renderBoard(analysisChess, lastMove);
        return;
      }

      let moved = null;
      try {
        moved = analysisChess.move({ from: from, to: sq, promotion: 'q' });
      } catch (_) { moved = null; }

      if (!moved) {
        analysisSelectedSq = null;
        let lastMove = null;
        if (exploreMode && exploreMoves.length) lastMove = exploreMoves[exploreMoves.length - 1];
        else if (analysisPly > 0 && analysisMoves[analysisPly - 1]) lastMove = analysisMoves[analysisPly - 1];
        renderBoard(analysisChess, lastMove);
        const hint = document.getElementById('arrowHint');
        if (hint) hint.textContent = '非法走法：请先点己方棋子，再点目标格';
        return;
      }

      // 若仍在主线且走的正是谱着 → 沿主线前进
      if (!exploreMode && analysisPly < analysisMoves.length) {
        const main = analysisMoves[analysisPly];
        const same = main && main.from === moved.from && main.to === moved.to &&
          (main.promotion || 'q') === (moved.promotion || 'q');
        if (same) {
          // 撤销刚才的 move，用 gotoPly 同步状态
          analysisChess.undo();
          analysisSelectedSq = null;
          gotoPly(analysisPly + 1);
          return;
        }
      }

      // 离开主线 → 对局浏览器
      enterExploreWithMove(moved);
    }

    document.getElementById('board')?.addEventListener('click', onAnalysisBoardClick);
    document.getElementById('btnExitExplore')?.addEventListener('click', () => {
      exitExploreMode(exploreBasePly);
    });



    // ---- Move quality glyphs (Chess.com-like) ----
    let moveAnnotations = []; // index by ply-1 after each move
    let annotateAbort = null;
    let annotating = false;

    const GLYPH_META = {
      brilliant: { cls: 'glyph-brilliant', text: '!!', title: '精妙' },
      great: { cls: 'glyph-great', text: '!', title: '好棋' },
      best: { cls: 'glyph-best', text: '★', title: '最佳' },
      excellent: { cls: 'glyph-excellent', text: '✓', title: '优秀' },
      good: { cls: 'glyph-good', text: '·', title: '不错' },
      book: { cls: 'glyph-book', text: 'A', title: '理论' },
      inaccuracy: { cls: 'glyph-inaccuracy', text: '?!', title: '可疑' },
      mistake: { cls: 'glyph-mistake', text: '?', title: '失误' },
      blunder: { cls: 'glyph-blunder', text: '??', title: '败着' },
      miss: { cls: 'glyph-miss', text: 'X', title: '错失' }
    };

    function glyphHtml(kind, detail) {
      const m = GLYPH_META[kind];
      if (!m) return '';
      const tip = m.title + (detail ? (' · ' + detail) : '');
      return '<span class="glyph ' + m.cls + '" title="' + tip + '">' + m.text + '</span>';
    }

    // eval from white POV in centipawns; mate -> large
    function normalizeCloudScore(pv) {
      if (!pv) return null;
      if (typeof pv.mate === 'number') {
        return pv.mate > 0 ? (100000 - pv.mate * 100) : (-100000 - pv.mate * 100);
      }
      if (typeof pv.cp === 'number') return pv.cp;
      return null;
    }


    const evalCache = new Map();
    let annEngine = null;
    let annEngineReady = false;
    let annEngineLoading = null;

    function loadAnnotateEngine() {
      if (annEngineReady && annEngine) return Promise.resolve(annEngine);
      if (annEngineLoading) return annEngineLoading;
      annEngineLoading = (async () => {
        const urls = [
          'https://cdn.jsdelivr.net/npm/stockfish.js@10.0.2/stockfish.js',
          'https://unpkg.com/stockfish.js@10.0.2/stockfish.js',
          'https://cdnjs.cloudflare.com/ajax/libs/stockfish.js/10.0.2/stockfish.js'
        ];
        for (const u of urls) {
          try {
            const res = await fetch(u);
            if (!res.ok) continue;
            const code = await res.text();
            const blobUrl = URL.createObjectURL(new Blob([code], { type: 'application/javascript' }));
            const w = new Worker(blobUrl);
            await new Promise((resolve, reject) => {
              const t = setTimeout(() => reject(new Error('engine timeout')), 12000);
              w.onmessage = (e) => {
                const line = String(e.data || '');
                if (line === 'uciok' || line === 'readyok') {
                  clearTimeout(t);
                  resolve();
                }
              };
              w.onerror = (err) => { clearTimeout(t); reject(err); };
              w.postMessage('uci');
              w.postMessage('isready');
            });
            annEngine = w;
            annEngineReady = true;
            annEngineLoading = null;
            return w;
          } catch (e) {
            console.warn('ann engine fail', u, e);
          }
        }
        annEngineLoading = null;
        throw new Error('local engine unavailable');
      })();
      return annEngineLoading;
    }

    // 串行评估队列，避免 stop/go 抢跑
    let engineEvalQueue = Promise.resolve();
    function engineEvalCp(fen, depth, movetimeMs) {
      const run = () => new Promise((resolve) => {
        if (!annEngine) return resolve(null);
        depth = depth || 0;
        movetimeMs = Math.max(80, movetimeMs || 200);
        const pvs = {};
        let resolved = false;
        let bestmoveUci = '';
        const finish = () => {
          if (resolved) return;
          resolved = true;
          try { annEngine.removeEventListener('message', onMsg); } catch (_) {}
          const list = Object.keys(pvs).map(Number).sort((a,b)=>a-b).map(k => pvs[k]);
          if (!list.length && bestmoveUci) {
            list.push({ uci: bestmoveUci, cpSide: 0, depth: 0 });
          }
          if (!list.length) return resolve(null);
          resolve({
            cpSide: list[0].cpSide,
            bestUci: list[0].uci || bestmoveUci || '',
            multipv: list,
            depth: list[0].depth || 0
          });
        };
        // 给足时间：movetime + 缓冲；中后盘更长
        const timer = setTimeout(finish, movetimeMs + 450);

        function onMsg(e) {
          const line = String(e.data || '');
          if (line.startsWith('info') && line.includes(' score ') && line.includes(' pv ')) {
            const dM = line.match(/\bdepth (\d+)/);
            const mp = line.match(/\bmultipv (\d+)/);
            const mMate = line.match(/\bscore mate (-?\d+)/);
            const mCp = line.match(/\bscore cp (-?\d+)/);
            const mPv = line.match(/\bpv ([a-h][1-8][a-h][1-8][qrbn]?)/);
            const rank = mp ? parseInt(mp[1], 10) : 1;
            let cpSide = null;
            if (mMate) {
              const mate = parseInt(mMate[1], 10);
              cpSide = mate > 0 ? (30000 - Math.abs(mate) * 100) : (-30000 - Math.abs(mate) * 100);
            } else if (mCp) {
              cpSide = parseInt(mCp[1], 10);
            }
            if (cpSide === null || !mPv) return;
            const dep = dM ? parseInt(dM[1], 10) : 0;
            if (!pvs[rank] || dep >= (pvs[rank].depth || 0)) {
              pvs[rank] = { uci: mPv[1], cpSide: cpSide, depth: dep };
            }
          }
          if (line.startsWith('bestmove')) {
            const bm = line.match(/^bestmove\s+([a-h][1-8][a-h][1-8][qrbn]?|0000)/);
            if (bm && bm[1] !== '0000') bestmoveUci = bm[1];
            clearTimeout(timer);
            // 短暂延迟再收，让最后的 multipv info 到位
            setTimeout(finish, 30);
          }
        }
        annEngine.addEventListener('message', onMsg);
        try {
          annEngine.postMessage('stop');
          annEngine.postMessage('setoption name MultiPV value 2');
          annEngine.postMessage('position fen ' + fen);
          annEngine.postMessage('go movetime ' + movetimeMs);
        } catch (err) {
          clearTimeout(timer);
          resolve(null);
        }
      });
      // 串行：上一步完成再搜下一步
      const job = engineEvalQueue.then(run, run);
      engineEvalQueue = job.catch(() => null);
      return job;
    }

    // Chess.com 观感：多数着法是理论/最佳/优秀/不错，?! 不应刷屏
    function classifyByGap(gapCp, playedWasBest, plyIndex, flags) {
      flags = flags || {};
      if (flags.mateWin) return 'best';
      if (flags.mateLoss) return 'blunder';

      const rank = flags.rank || 0; // 1=最佳, 2, 3, 0=未进前三
      gapCp = Math.max(0, Number(gapCp) || 0);
      const inOpening = plyIndex < 20; // 前 10 回合

      // 引擎最佳或分差极小
      if (playedWasBest || rank === 1 || gapCp <= 12) {
        return inOpening ? 'book' : 'best';
      }

      // 前三佳着：从宽
      if (rank === 2) {
        if (inOpening) return 'book';
        return gapCp <= 60 ? 'excellent' : 'good';
      }
      if (rank === 3) {
        if (inOpening) return gapCp <= 100 ? 'book' : 'good';
        return gapCp <= 80 ? 'good' : 'inaccuracy';
      }

      // 未进前三：才用分差，且阈值宽松
      if (inOpening) {
        if (gapCp <= 120) return 'book';
        if (gapCp <= 180) return 'good';
        if (gapCp <= 280) return 'inaccuracy';
        if (gapCp <= 450) return 'mistake';
        return 'blunder';
      }

      if (gapCp <= 45) return 'excellent';
      if (gapCp <= 90) return 'good';
      if (gapCp <= 160) return 'inaccuracy';
      if (gapCp <= 280) return 'mistake';
      return 'blunder';
    }


    // ===== Chess.com-style review summary =====
    function reviewAccuracyFromGap(gap) {
      // 平滑惩罚：0cp≈100%，100cp≈约85%，300cp≈约63%，避免少量大失误把分数打成0。
      const g = Math.max(0, Number(gap) || 0);
      return Math.max(0, Math.min(100, 100 * Math.exp(-g / 420)));
    }

    function renderGameReviewSummary() {
      const wrap = document.getElementById('reviewSummary');
      const playersEl = document.getElementById('reviewPlayers');
      const phaseEl = document.getElementById('reviewPhase');
      if (!wrap || !playersEl || !phaseEl || !analysisGame || !analysisMoves.length || !moveAnnotations.length) return;

      const me = analysisGame.isWhite ? 'white' : 'black';
      const players = {
        white: { name: '白方', rating: analysisGame.isWhite ? analysisGame.myRating : analysisGame.oppRating, counts: {}, sum: 0, n: 0 },
        black: { name: '黑方', rating: analysisGame.isWhite ? analysisGame.oppRating : analysisGame.myRating, counts: {}, sum: 0, n: 0 }
      };
      const phases = {
        opening: { label:'开局', range:'1–10 回合', white:{sum:0,n:0,bad:0}, black:{sum:0,n:0,bad:0} },
        middlegame: { label:'中局', range:'11–25 回合', white:{sum:0,n:0,bad:0}, black:{sum:0,n:0,bad:0} },
        endgame: { label:'残局', range:'26+ 回合', white:{sum:0,n:0,bad:0}, black:{sum:0,n:0,bad:0} }
      };
      const order = ['brilliant','great','best','excellent','good','book','inaccuracy','mistake','blunder','miss'];
      const short = { brilliant:'!!', great:'!', best:'★', excellent:'✓', good:'·', book:'A', inaccuracy:'?!', mistake:'?', blunder:'??', miss:'X' };

      analysisMoves.forEach((mv, i) => {
        const ann = moveAnnotations[i] || {kind:'good',gap:35};
        const side = (i % 2 === 0) ? 'white' : 'black';
        const g = Math.max(0, Number(ann.gap) || 0);
        const acc = reviewAccuracyFromGap(g);
        const pl = players[side];
        pl.sum += acc; pl.n++;
        pl.counts[ann.kind] = (pl.counts[ann.kind] || 0) + 1;
        const moveNo = Math.floor(i / 2) + 1;
        const phase = moveNo <= 10 ? phases.opening : moveNo <= 25 ? phases.middlegame : phases.endgame;
        phase[side].sum += acc; phase[side].n++;
        if (['inaccuracy','mistake','blunder','miss'].includes(ann.kind)) phase[side].bad++;
      });

      const playerHtml = ['white','black'].map(side => {
        const p = players[side];
        const accuracy = p.n ? p.sum / p.n : 0;
        const isMe = side === me;
        const counts = order.filter(k => p.counts[k]).map(k =>
          '<span><i class="glyph ' + (GLYPH_META[k]?.cls || 'glyph-good') + '">' + (short[k] || '·') + '</i>' + p.counts[k] + '</span>'
        ).join('');
        return `<div class="review-player ${isMe ? 'me' : ''}">
          <div class="review-player-head"><div class="review-player-name">${isMe ? '你' : '对手'} · ${p.name}</div><div class="review-rating">${p.rating != null ? Math.round(Number(p.rating)) : '—'} 分</div></div>
          <div class="review-accuracy">${accuracy.toFixed(1)}%</div><div class="review-accuracy-label">精度</div>
          <div class="review-glyph-counts">${counts || '<span>暂无角标</span>'}</div>
        </div>`;
      }).join('');
      playersEl.innerHTML = playerHtml;

      const phaseRows = Object.values(phases).map(ph => {
        const w = ph.white.n ? ph.white.sum / ph.white.n : 0;
        const b = ph.black.n ? ph.black.sum / ph.black.n : 0;
        return `<tr><td class="phase-name">${ph.label}<div style="font-size:.62rem;color:#aaa7a3;font-weight:400">${ph.range}</div></td>
          <td>${w.toFixed(1)}%<div class="review-bar"><i style="width:${w}%"></i></div><div style="font-size:.61rem;color:#aaa7a3">${ph.white.bad} 次明显失误</div></td>
          <td>${b.toFixed(1)}%<div class="review-bar"><i style="width:${b}%"></i></div><div style="font-size:.61rem;color:#aaa7a3">${ph.black.bad} 次明显失误</div></td></tr>`;
      }).join('');
      phaseEl.innerHTML = `<table><thead><tr><th>阶段</th><th>白方</th><th>黑方</th></tr></thead><tbody>${phaseRows}</tbody></table>`;
      wrap.classList.remove('hidden');
    }

    async function annotateGame() {
      if (!analysisMoves || !analysisMoves.length) {
        alert('没有着法可分析');
        return;
      }
      if (annotating) return;

      annotating = true;
      if (annotateAbort) { try { annotateAbort.abort(); } catch (_) {} }
      annotateAbort = new AbortController();
      const signal = annotateAbort.signal;

      const btnA = document.getElementById('btnAnnotate');
      const btnE = document.getElementById('btnEngine');
      const status = document.getElementById('engineStatus');
      btnA.disabled = true;
      btnE.disabled = true;
      btnA.textContent = '生成中…';

      moveAnnotations = new Array(analysisMoves.length).fill(null);
      evalCache.clear();

      const chess = new (getChessCtor())();
      const beforeFens = [];
      for (let i = 0; i < analysisMoves.length; i++) {
        beforeFens.push(chess.fen());
        chess.move(analysisMoves[i]);
      }
      const finalFen = chess.fen();

      // 持久化角标缓存：同一局（FEN 序列）不重复算
      const annCacheKey = 'ann-cache:' + (analysisGame && analysisGame.id ? analysisGame.id : '') + ':' + beforeFens.length + ':' + (beforeFens[0] || '').slice(0, 24);
      try {
        const cached = JSON.parse(localStorage.getItem(annCacheKey) || 'null');
        if (cached && Array.isArray(cached) && cached.length === analysisMoves.length) {
          moveAnnotations = cached;
          buildMoveList();
          const ply = analysisPly;
          analysisChess.reset();
          let last = null;
          for (let j = 0; j < ply; j++) last = analysisChess.move(analysisMoves[j]);
          renderBoard(analysisChess, last);
          renderGameReviewSummary();
          status.textContent = '已从缓存加载角标（' + moveAnnotations.length + ' 步）';
          btnA.textContent = '生成角标';
          btnA.disabled = false;
          btnE.disabled = false;
          annotating = false;
          return;
        }
      } catch (_) {}

      let useLocal = false;
      status.textContent = '准备引擎…';
      try {
        await loadAnnotateEngine();
        useLocal = true;
      } catch (e) {
        useLocal = false;
      }

      const t0 = performance.now();
      // 每步：在「走之前」的局面做 MultiPV，比较实际着与最佳着的分差
      const perMove = new Array(analysisMoves.length).fill(null);

      try {
        if (useLocal) {
          // 两遍策略：快扫 + 仅可疑着法深搜 → 兼顾速度与准度
          // 不在标注阶段搜「对方威胁」（查看着法时再算），可省近一半时间
          const n = analysisMoves.length;
          const firstPass = new Array(n).fill(null);

          for (let i = 0; i < n; i++) {
            if (signal.aborted) break;
            status.textContent = '快扫 ' + (i + 1) + '/' + n;
            const fen = beforeFens[i];
            const mv = analysisMoves[i];
            const promo = mv.promotion ? String(mv.promotion).toLowerCase()[0] : '';
            const playedUci = (mv.from || '') + (mv.to || '') + promo;

            // 开局更快，中后盘稍慢但仍控制总时长
            const mt = i < 16 ? 140 : (i < 36 ? 200 : 260);
            const r = await engineEvalCp(fen, 0, mt);

            let gap = 35, wasBest = false, bestUci = '', bestSan = '', rank = 0;
            let needDeep = true;

            if (r && r.multipv && r.multipv.length && typeof r.multipv[0].cpSide === 'number') {
              bestUci = r.bestUci || r.multipv[0].uci || '';
              const cpBest = r.multipv[0].cpSide;
              let found = null, foundRank = 0;
              for (let ri = 0; ri < r.multipv.length; ri++) {
                const line = r.multipv[ri];
                if (!line.uci) continue;
                if (line.uci.slice(0, 4) === playedUci.slice(0, 4)) {
                  if (!line.uci[4] || !promo || line.uci[4] === promo) {
                    found = line; foundRank = ri + 1; break;
                  }
                }
              }
              if (found && typeof found.cpSide === 'number') {
                rank = foundRank;
                wasBest = rank === 1;
                gap = Math.max(0, cpBest - found.cpSide);
                // 已在 MultiPV 内且分差明确 → 无需深搜
                needDeep = false;
              } else if (bestUci && playedUci && bestUci.slice(0, 4) === playedUci.slice(0, 4)) {
                wasBest = true; rank = 1; gap = 0; needDeep = false;
              } else {
                // 不在前二：需要深搜确认分差
                needDeep = true;
                gap = 80;
              }
            }

            try {
              if (bestUci && bestUci.length >= 4) {
                const tc = new (getChessCtor())(fen);
                const m1 = tc.move({ from: bestUci.slice(0,2), to: bestUci.slice(2,4), promotion: bestUci[4] || 'q' });
                if (m1) bestSan = m1.san;
              }
            } catch (_) {}

            const afterPos = new (getChessCtor())(fen);
            afterPos.move(mv);
            const mateWin = (typeof afterPos.in_checkmate === 'function')
              ? afterPos.in_checkmate()
              : (afterPos.isCheckmate ? afterPos.isCheckmate() : false);

            firstPass[i] = {
              kind: null, gap, wasBest, rank, bestUci, bestSan,
              replyUci: '', replySan: '', epl: null, cpl: gap,
              needDeep, mateWin: !!mateWin, fen, playedUci, promo, mv
            };
          }

          // 第二遍：只深搜可疑着（不在 MultiPV / 可能失误）
          const deepIdx = [];
          for (let i = 0; i < n; i++) {
            const fp = firstPass[i];
            if (!fp || fp.mateWin) continue;
            if (fp.needDeep || (!fp.wasBest && fp.gap >= 40)) deepIdx.push(i);
          }
          for (let di = 0; di < deepIdx.length; di++) {
            if (signal.aborted) break;
            const i = deepIdx[di];
            status.textContent = '精校 ' + (di + 1) + '/' + deepIdx.length + '（可疑着）';
            const fp = firstPass[i];
            const fen = fp.fen;
            const mt = i < 24 ? 380 : 520;
            const r = await engineEvalCp(fen, 0, mt);
            const mv = fp.mv;
            const promo = fp.promo;
            const playedUci = fp.playedUci;

            if (r && r.multipv && r.multipv.length && typeof r.multipv[0].cpSide === 'number') {
              const cpBest = r.multipv[0].cpSide;
              fp.bestUci = r.bestUci || r.multipv[0].uci || '';
              let found = null, foundRank = 0;
              for (let ri = 0; ri < r.multipv.length; ri++) {
                const line = r.multipv[ri];
                if (!line.uci) continue;
                if (line.uci.slice(0, 4) === playedUci.slice(0, 4)) {
                  if (!line.uci[4] || !promo || line.uci[4] === promo) {
                    found = line; foundRank = ri + 1; break;
                  }
                }
              }
              if (found && typeof found.cpSide === 'number') {
                fp.rank = foundRank;
                fp.wasBest = foundRank === 1;
                fp.gap = Math.max(0, cpBest - found.cpSide);
              } else if (fp.bestUci && playedUci && fp.bestUci.slice(0, 4) === playedUci.slice(0, 4)) {
                fp.wasBest = true; fp.rank = 1; fp.gap = 0;
              } else {
                const tmp = new (getChessCtor())(fen);
                tmp.move(mv);
                const after = await engineEvalCp(tmp.fen(), 0, Math.round(mt * 0.7));
                if (after && typeof after.cpSide === 'number') {
                  fp.gap = Math.max(0, cpBest - (-after.cpSide));
                  fp.rank = 0;
                  fp.wasBest = false;
                } else {
                  fp.gap = Math.max(fp.gap, 50);
                  fp.wasBest = false;
                  fp.rank = 0;
                }
              }
              try {
                if (fp.bestUci && fp.bestUci.length >= 4) {
                  const tc = new (getChessCtor())(fen);
                  const m1 = tc.move({ from: fp.bestUci.slice(0,2), to: fp.bestUci.slice(2,4), promotion: fp.bestUci[4] || 'q' });
                  if (m1) fp.bestSan = m1.san;
                }
              } catch (_) {}
            }
            fp.cpl = fp.gap;
          }

          for (let i = 0; i < n; i++) {
            const fp = firstPass[i];
            if (!fp) {
              perMove[i] = { kind: 'good', gap: 35, wasBest: false, rank: 0, bestUci: '', bestSan: '', replyUci: '', replySan: '', epl: null, cpl: 35 };
              continue;
            }
            const kind = classifyByGap(fp.gap, fp.wasBest, i, { mateWin: fp.mateWin, mateLoss: false, rank: fp.rank });
            perMove[i] = {
              kind, gap: fp.gap, wasBest: fp.wasBest, rank: fp.rank,
              bestUci: fp.bestUci, bestSan: fp.bestSan,
              replyUci: '', replySan: '', epl: null, cpl: fp.gap
            };
          }
                } else {
          // 云库降级：并行取分，再用前后分差
          status.textContent = '云库模式（精度较低）…';
          for (let i = 0; i < analysisMoves.length; i++) {
            if (signal.aborted) break;
            status.textContent = '云库 ' + (i + 1) + '/' + analysisMoves.length;
            const fen = beforeFens[i];
            const beforeEv = await fetchEvalWhiteCp(fen, signal);
            const tmp = new (getChessCtor())(fen);
            tmp.move(analysisMoves[i]);
            const afterEv = await fetchEvalWhiteCp(tmp.fen(), signal);
            const moverIsWhite = fen.split(' ')[1] !== 'b';
            let gap = 40;
            let wasBest = false;
            let bestUci = beforeEv ? (beforeEv.bestUci || '') : '';
            const mv = analysisMoves[i];
            const playedUci = (mv.from || '') + (mv.to || '') + (mv.promotion ? String(mv.promotion)[0] : '');
            if (bestUci && playedUci && bestUci.slice(0,4) === playedUci.slice(0,4)) {
              wasBest = true;
              gap = 0;
            } else if (beforeEv && afterEv) {
              const b = moverIsWhite ? beforeEv.cp : -beforeEv.cp;
              const a = moverIsWhite ? afterEv.cp : -afterEv.cp;
              gap = Math.max(0, b - a);
            }
            let bestSan = '';
            try {
              if (bestUci.length >= 4) {
                const t = new (getChessCtor())(fen);
                const m1 = t.move({ from: bestUci.slice(0,2), to: bestUci.slice(2,4), promotion: bestUci[4] || 'q' });
                if (m1) bestSan = m1.san;
              }
            } catch (_) {}
            const mateWin = (typeof tmp.in_checkmate === 'function') ? tmp.in_checkmate() : false;
            const kind = classifyByGap(gap, wasBest, i, { mateWin: !!mateWin });
            perMove[i] = {
              kind: kind, gap: gap, wasBest: wasBest,
              bestUci: bestUci, bestSan: bestSan,
              replyUci: afterEv ? (afterEv.bestUci || '') : '',
              replySan: '', epl: null, cpl: gap
            };
          }
        }

        for (let i = 0; i < analysisMoves.length; i++) {
          moveAnnotations[i] = perMove[i] || {
            kind: 'good', gap: 0, wasBest: false,
            bestUci: '', bestSan: '', replyUci: '', replySan: '', epl: null, cpl: 0
          };
        }

        buildMoveList();
        const ply = analysisPly;
        analysisChess.reset();
        let last = null;
        for (let j = 0; j < ply; j++) last = analysisChess.move(analysisMoves[j]);
        renderBoard(analysisChess, last);
        document.querySelectorAll('#moveList span[data-ply]').forEach(el => {
          el.classList.toggle('active', parseInt(el.dataset.ply, 10) === ply);
        });

        const ms = Math.round(performance.now() - t0);
        const dist = {};
        moveAnnotations.forEach(a => { if (a) dist[a.kind] = (dist[a.kind] || 0) + 1; });
        const order = ['book','best','excellent','good','inaccuracy','mistake','blunder'];
        const distStr = order.filter(k => dist[k]).map(k => (GLYPH_META[k] ? GLYPH_META[k].title : k) + dist[k]).join(' ');
        renderGameReviewSummary();
        status.textContent = '完成 ' + moveAnnotations.length + ' 步 · ' + (ms/1000).toFixed(1) + 's · ' +
          (useLocal ? 'MultiPV' : '云库') + (distStr ? '｜' + distStr : '');
        try {
          if (annCacheKey) localStorage.setItem(annCacheKey, JSON.stringify(moveAnnotations));
        } catch (_) {}
      } catch (err) {
        console.error(err);
        status.textContent = '角标生成出错：' + (err.message || err);
      }

      btnA.textContent = '生成角标';
      btnA.disabled = false;
      btnE.disabled = false;
      annotating = false;
      try {
        if (typeof buildMoveList === 'function') buildMoveList();
        // 刷新当前步的复盘箭头（绿=最佳着）
        clearLiveEvalArrows();
        if (analysisChess) {
          let last = null;
          if (analysisPly > 0 && analysisMoves[analysisPly - 1]) {
            // 仅用于高亮最后一着，不重新走子
            last = analysisMoves[analysisPly - 1];
          }
          renderBoard(analysisChess, last);
        } else {
          updateThreatArrows();
        }
      } catch (e) { console.warn(e); }
    }


    // ---- Evaluation: cloud first, remote API, then local ----
    let evalAbort = null;
    let localEngine = null;
    let localEngineReady = false;
    let localEngineKind = null; // 'stockfish' | 'lozza'
    let lozzaEngine = null;
    let lozzaEngineReady = false;

    function getSelectedEngine() {
      const el = document.getElementById('engineChoice');
      return (el && el.value) || 'auto';
    }
    function getSelectedDepth() {
      const el = document.getElementById('engineDepth');
      const d = parseInt(el && el.value, 10);
      return (d >= 6 && d <= 30) ? d : 14;
    }

    async function requestEval(forceLocal) {
      if (!analysisChess) return;
      if (annotating) {
        document.getElementById('engineStatus').textContent = '正在生成角标，请稍候…';
        return;
      }
      const fen = analysisChess.fen();
      const choice = forceLocal ? 'stockfish' : getSelectedEngine();
      const depth = getSelectedDepth();
      document.getElementById('engineStatus').textContent = '正在评估…';
      document.getElementById('engineLines').innerHTML = '';
      document.getElementById('btnEngine').textContent = '评估中…';
      clearLiveEvalArrows();
      updateThreatArrows();

      if (evalAbort) { try { evalAbort.abort(); } catch (_) {} }
      evalAbort = new AbortController();
      const signal = evalAbort.signal;

      // 强制本地引擎 / 选手动选择
      if (choice === 'stockfish') {
        startLocalEngine(fen, depth, 'stockfish');
        return;
      }
      if (choice === 'lozza') {
        startLocalEngine(fen, depth, 'lozza');
        return;
      }
      // Reckless / PlentyChess：目前仅有桌面二进制，浏览器无法直接运行
      if (choice === 'reckless' || choice === 'plenty') {
        const name = choice === 'reckless' ? 'Reckless' : 'PlentyChess';
        document.getElementById('engineLines').innerHTML = '';
        document.getElementById('engineStatus').textContent =
          name + ' 目前只有桌面端版本（Windows/Linux/macOS），无法在浏览器内加载。' +
          '请改选「Stockfish 18」或「自动」进行分析。';
        document.getElementById('btnEngine').textContent = '重新评估';
        return;
      }

      // auto：云库 → 在线 API → 本地鳕鱼
      if (!forceLocal) {
        // 1) Lichess cloud
        try {
          const url = 'https://lichess.org/api/cloud-eval?fen=' + encodeURIComponent(fen) + '&multiPv=3';
          const res = await fetch(url, { signal });
          if (res.ok) {
            const data = await res.json();
            if (data && data.pvs && data.pvs.length) {
              applyCloudEval(data, 'Lichess 云库');
              document.getElementById('btnEngine').textContent = '重新评估';
              return;
            }
          } else if (res.status === 404) {
            console.log('cloud miss');
          }
        } catch (e) {
          if (e.name === 'AbortError') return;
          console.warn('lichess cloud failed', e);
        }

        // 2) chess-api.com remote Stockfish（使用所选深度）
        try {
          const res = await fetch('https://chess-api.com/v1', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ fen: fen, depth: depth }),
            signal
          });
          if (res.ok) {
            const data = await res.json();
            if (data && (data.eval !== undefined || data.mate !== undefined || data.move)) {
              applyChessApiEval(data);
              document.getElementById('btnEngine').textContent = '重新评估';
              return;
            }
          }
        } catch (e) {
          if (e.name === 'AbortError') return;
          console.warn('chess-api failed', e);
        }
      }

      // 3) local stockfish
      startLocalEngine(fen, depth, 'stockfish');
    }

    function scoreToBar(cpWhite) {
      let whitePct = 50 + 50 * (2 / (1 + Math.exp(-cpWhite / 280)) - 1);
      return Math.max(2, Math.min(98, whitePct));
    }

    function applyCloudEval(data, label) {
      const linesEl = document.getElementById('engineLines');
      linesEl.innerHTML = '';
      let topScoreText = '—';
      let whitePct = 50;

      data.pvs.slice(0, 3).forEach((pv, i) => {
        let scoreText = '—';
        let cpForBar = 0;
        if (typeof pv.mate === 'number') {
          const mate = pv.mate; // white POV
          scoreText = mate > 0 ? ('M' + mate) : ('-M' + (-mate));
          cpForBar = mate > 0 ? 10000 : -10000;
        } else if (typeof pv.cp === 'number') {
          const cp = pv.cp;
          scoreText = (cp > 0 ? '+' : '') + (cp / 100).toFixed(1);
          cpForBar = cp;
        }
        if (i === 0) {
          topScoreText = scoreText;
          whitePct = scoreToBar(cpForBar);
        }
        const uciMoves = (pv.moves || '').trim().split(/\s+/).filter(Boolean).slice(0, 8);
        const sans = uciToSanList(analysisChess.fen(), uciMoves);
        const div = document.createElement('div');
        div.className = 'engine-line';
        div.innerHTML = '<strong>' + scoreText + '</strong> <span style="opacity:.55">云</span> ' + sans.join(' ');
        linesEl.appendChild(div);
      });

      document.getElementById('evalScore').textContent = topScoreText;
      document.getElementById('evalBar').style.width = whitePct + '%';
      const depth = data.depth || '?';
      document.getElementById('engineStatus').textContent = (label || '云评估') + ' · 深度 ' + depth;
      // 箭头：主变 + 其它 PV
      try {
        const pvs = data.pvs || [];
        let bestU = '';
        const alts = [];
        pvs.forEach((pv, i) => {
          const parts = String(pv.moves || '').trim().split(/\s+/).filter(Boolean);
          if (!parts.length) return;
          if (i === 0) bestU = parts[0];
          else alts.push(parts[0]);
        });
        setLiveEvalArrows(bestU, alts);
      } catch (_) {}
    }

    function applyChessApiEval(data) {
      // chess-api.com: eval is from side to move? docs say evaluation number, mate, move, san, continuation
      const turnIsWhite = analysisChess.turn() === 'w';
      let scoreText = '—';
      let cpWhite = 0;

      if (data.mate !== undefined && data.mate !== null && data.mate !== 0) {
        let mate = Number(data.mate);
        // assume side-to-move POV for mate/eval on this API
        if (!turnIsWhite) mate = -mate;
        scoreText = mate > 0 ? ('M' + Math.abs(mate)) : ('-M' + Math.abs(mate));
        if (mate < 0 && turnIsWhite) scoreText = '-M' + Math.abs(mate);
        if (mate > 0 && !turnIsWhite) scoreText = '-M' + Math.abs(mate);
        // normalize display white POV:
        let mateWhite = Number(data.mate);
        if (!turnIsWhite) mateWhite = -mateWhite;
        scoreText = mateWhite > 0 ? ('M' + mateWhite) : ('-M' + (-mateWhite));
        cpWhite = mateWhite > 0 ? 10000 : -10000;
      } else if (data.eval !== undefined && data.eval !== null) {
        let ev = Number(data.eval); // often in pawns, side to move
        let cp = Math.round(ev * 100);
        if (!turnIsWhite) cp = -cp;
        scoreText = (cp > 0 ? '+' : '') + (cp / 100).toFixed(1);
        cpWhite = cp;
      }

      let lineText = '';
      if (data.continuationArr && data.continuationArr.length) {
        lineText = data.continuationArr.slice(0, 6).map(function (x) {
          return x.san || x.move || '';
        }).filter(Boolean).join(' ');
      } else if (data.san || data.move) {
        lineText = data.san || data.move;
        if (data.continuation) lineText += ' ' + String(data.continuation).split(' ').slice(0, 5).join(' ');
      }

      document.getElementById('evalScore').textContent = scoreText;
      document.getElementById('evalBar').style.width = scoreToBar(cpWhite) + '%';
      document.getElementById('engineLines').innerHTML =
        '<div class="engine-line"><strong>' + scoreText + '</strong> <span style="opacity:.55">在线引擎</span> ' + lineText + '</div>';
      document.getElementById('engineStatus').textContent = '在线 Stockfish · 深度 ' + (data.depth || '12');
      try {
        let bestU = '';
        if (data.move && /^[a-h][1-8][a-h][1-8]/.test(String(data.move))) bestU = String(data.move);
        else if (data.continuationArr && data.continuationArr[0] && data.continuationArr[0].move)
          bestU = String(data.continuationArr[0].move);
        else if (data.san) {
          // 尝试把 SAN 转 UCI
          try {
            const t = new (getChessCtor())(analysisChess.fen());
            const m = t.move(data.san);
            if (m) bestU = m.from + m.to + (m.promotion || '');
          } catch (_) {}
        }
        setLiveEvalArrows(bestU, []);
      } catch (_) {}
    }

    function uciToSanList(fen, uciMoves) {
      try {
        const tmp = new (getChessCtor())(fen);
        const sans = [];
        for (const u of uciMoves) {
          try {
            const m = tmp.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u[4] || 'q' });
            if (m) sans.push(m.san); else break;
          } catch (_) { break; }
        }
        return sans;
      } catch (_) { return uciMoves; }
    }

    async function ensureEngineWorker(kind) {
      // kind: 'stockfish' | 'lozza'
      if (kind === 'lozza') {
        if (lozzaEngine && lozzaEngineReady) return lozzaEngine;
        const urls = [
          'https://cdn.jsdelivr.net/gh/op12no2/lozza@master/lozza.js',
          'https://cdn.jsdelivr.net/gh/op12no2/lozza@master/lozza.js'
        ];
        let lastErr = null;
        for (const u of urls) {
          try {
            const res = await fetch(u);
            if (!res.ok) throw new Error('fetch ' + res.status);
            const code = await res.text();
            // Lozza 可作为 Worker 运行；部分环境需包一层 onmessage 桥
            const wrapped = code + '\n' +
              '// bridge: if not already worker-aware\n' +
              'if (typeof onmessage === "undefined" && typeof self !== "undefined") {\n' +
              '  /* lozza usually sets handlers itself */\n' +
              '}\n';
            const blob = new Blob([code], { type: 'application/javascript' });
            const blobUrl = URL.createObjectURL(blob);
            const w = new Worker(blobUrl);
            await new Promise((resolve, reject) => {
              const t = setTimeout(() => reject(new Error('lozza timeout')), 12000);
              w.onmessage = function (e) {
                const line = String(e.data || '');
                if (line === 'uciok' || line.indexOf('id name') === 0 || line === 'readyok') {
                  clearTimeout(t);
                  resolve();
                }
              };
              w.onerror = function (err) { clearTimeout(t); reject(err); };
              try {
                w.postMessage('uci');
                w.postMessage('isready');
              } catch (err) { clearTimeout(t); reject(err); }
            });
            lozzaEngine = w;
            lozzaEngineReady = true;
            return w;
          } catch (e) {
            lastErr = e;
            console.warn('lozza load fail', u, e);
          }
        }
        throw lastErr || new Error('Lozza 不可用');
      }

      // stockfish (鳕鱼)
      if (localEngine && localEngineReady && localEngineKind === 'stockfish') return localEngine;
      // 若之前加载过其他类型，重建
      if (localEngine && localEngineKind !== 'stockfish') {
        try { localEngine.terminate(); } catch (_) {}
        localEngine = null;
        localEngineReady = false;
      }
      const workerUrls = [
        'https://cdn.jsdelivr.net/npm/stockfish.js@10.0.2/stockfish.js',
        'https://unpkg.com/stockfish.js@10.0.2/stockfish.js',
        'https://cdnjs.cloudflare.com/ajax/libs/stockfish.js/10.0.2/stockfish.js'
      ];
      let lastErr = null;
      for (const u of workerUrls) {
        try {
          const res = await fetch(u);
          if (!res.ok) throw new Error('fetch ' + res.status);
          const code = await res.text();
          const blob = new Blob([code], { type: 'application/javascript' });
          const blobUrl = URL.createObjectURL(blob);
          const w = new Worker(blobUrl);
          await new Promise((resolve, reject) => {
            const t = setTimeout(() => reject(new Error('stockfish timeout')), 12000);
            w.onmessage = function (e) {
              const line = String(e.data || '');
              if (line === 'uciok' || line === 'readyok') {
                clearTimeout(t);
                resolve();
              }
            };
            w.onerror = function (err) { clearTimeout(t); reject(err); };
            w.postMessage('uci');
            w.postMessage('isready');
          });
          localEngine = w;
          localEngineReady = true;
          localEngineKind = 'stockfish';
          console.log('local stockfish from', u);
          return w;
        } catch (e) {
          lastErr = e;
          console.warn('stockfish load fail', u, e);
        }
      }
      // direct worker fallback
      for (const u of workerUrls) {
        try {
          const w = new Worker(u);
          localEngine = w;
          localEngineReady = false;
          localEngineKind = 'stockfish';
          return w;
        } catch (e) { lastErr = e; }
      }
      throw lastErr || new Error('本地鳕鱼不可用');
    }

    async function startLocalEngine(fen, depth, kind) {
      depth = depth || getSelectedDepth();
      kind = kind || 'stockfish';
      const label = kind === 'lozza' ? 'Lozza' : '本地鳕鱼 Stockfish';
      document.getElementById('engineStatus').textContent = '正在启动 ' + label + '（深度 ' + depth + '）…';

      let worker;
      try {
        worker = await ensureEngineWorker(kind);
      } catch (e) {
        document.getElementById('engineStatus').textContent =
          label + ' 不可用：' + (e && e.message ? e.message : e) + '。可改选「自动」或换网络后重试。';
        document.getElementById('btnEngine').textContent = '重新评估';
        return;
      }

      // 统一消息处理
      const onMsg = function (e) {
        const line = typeof e.data === 'string' ? e.data : String(e.data || '');
        if (line === 'uciok' || line === 'readyok') {
          if (kind === 'stockfish') localEngineReady = true;
          if (kind === 'lozza') lozzaEngineReady = true;
          try {
            worker.postMessage('ucinewgame');
            worker.postMessage('position fen ' + fen);
            worker.postMessage('go depth ' + depth);
          } catch (err) {
            document.getElementById('engineStatus').textContent = '引擎通信失败';
            document.getElementById('btnEngine').textContent = '重新评估';
          }
          return;
        }
        if (line.startsWith('info') && line.includes(' score ')) {
          parseLocalInfo(line, label);
        }
        if (line.startsWith('bestmove')) {
          document.getElementById('engineStatus').textContent = label + ' 分析完成 · 深度 ' + depth;
          document.getElementById('btnEngine').textContent = '重新评估';
        }
      };

      worker.onmessage = onMsg;
      worker.onerror = function (err) {
        console.warn(label + ' error', err);
        document.getElementById('engineStatus').textContent = label + ' 运行出错';
        document.getElementById('btnEngine').textContent = '重新评估';
      };

      try {
        worker.postMessage('stop');
        worker.postMessage('ucinewgame');
        worker.postMessage('position fen ' + fen);
        worker.postMessage('go depth ' + depth);
        document.getElementById('engineStatus').textContent = label + ' 分析中 · 目标深度 ' + depth;
      } catch (err) {
        // 尚未 ready：先发 uci
        try {
          worker.postMessage('uci');
          worker.postMessage('isready');
        } catch (e2) {
          document.getElementById('engineStatus').textContent = label + ' 启动失败';
          document.getElementById('btnEngine').textContent = '重新评估';
        }
      }
    }

    function parseLocalInfo(line, engineLabel) {
      const depthM = line.match(/\bdepth (\d+)/);
      const scoreCp = line.match(/\bscore cp (-?\d+)/);
      const scoreMate = line.match(/\bscore mate (-?\d+)/);
      const pvM = line.match(/\bpv ([a-h][1-8][a-h][1-8](?:[qrbn])?(?:\s+[a-h][1-8][a-h][1-8](?:[qrbn])?)*)/);
      const turnIsWhite = analysisChess.turn() === 'w';
      let scoreText = '—';
      let cpWhite = 0;
      const tag = engineLabel || '本地引擎';

      if (scoreMate) {
        let mate = parseInt(scoreMate[1], 10); // side to move
        if (!turnIsWhite) mate = -mate;
        scoreText = mate > 0 ? ('M' + mate) : ('-M' + (-mate));
        cpWhite = mate > 0 ? 10000 : -10000;
      } else if (scoreCp) {
        let cp = parseInt(scoreCp[1], 10);
        if (!turnIsWhite) cp = -cp;
        scoreText = (cp > 0 ? '+' : '') + (cp / 100).toFixed(1);
        cpWhite = cp;
      }
      document.getElementById('evalScore').textContent = scoreText;
      document.getElementById('evalBar').style.width = scoreToBar(cpWhite) + '%';

      if (pvM && depthM) {
        const depth = depthM[1];
        const uciMoves = pvM[1].trim().split(/\s+/).slice(0, 6);
        const sans = uciToSanList(analysisChess.fen(), uciMoves);
        document.getElementById('engineLines').innerHTML =
          '<div class="engine-line"><strong>' + scoreText + '</strong> <span style="opacity:.55">d' + depth + ' · ' + tag + '</span> ' + sans.join(' ') + '</div>';
        document.getElementById('engineStatus').textContent = tag + ' 分析中 · 深度 ' + depth;
        if (uciMoves.length) setLiveEvalArrows(uciMoves[0], uciMoves.slice(1, 3));
      }
    }

