    // 时制多选：勾「全部」则取消各项；勾任一时制则取消「全部」
    (function setupTimeFilterUI() {
      const allBox = document.getElementById('timeAll');
      const opts = () => Array.from(document.querySelectorAll('.time-opt'));
      const syncChip = (input) => {
        const lab = input.closest('.time-chip');
        if (lab) lab.classList.toggle('is-on', input.checked);
      };
      const syncAll = () => {
        syncChip(allBox);
        opts().forEach(syncChip);
      };
      if (!allBox) return;
      allBox.addEventListener('change', () => {
        if (allBox.checked) opts().forEach(o => { o.checked = false; });
        else if (!opts().some(o => o.checked)) allBox.checked = true;
        syncAll();
      });
      opts().forEach(o => {
        o.addEventListener('change', () => {
          if (o.checked) allBox.checked = false;
          else if (!opts().some(x => x.checked)) allBox.checked = true;
          syncAll();
        });
      });
      syncAll();
    })();

