    function svgBarChart(items, opts) {
      opts = opts || {};
      const w = opts.width || 520, h = opts.height || 180, pad = 28;
      if (!items.length) return '<p style="opacity:.6">暂无数据</p>';
      const maxV = Math.max(...items.map(i => i.v), 0.01);
      const bw = (w - pad * 2) / items.length;
      let rects = '';
      items.forEach((it, i) => {
        const bh = ((h - pad * 2) * it.v) / maxV;
        const x = pad + i * bw + 4;
        const y = h - pad - bh;
        rects += `<rect x="${x}" y="${y}" width="${Math.max(8, bw - 8)}" height="${Math.max(1, bh)}" rx="4" fill="${it.color || 'var(--accent,#81b64c)'}" opacity="0.9"/>`;
        rects += `<text x="${x + (bw - 8) / 2}" y="${h - 8}" text-anchor="middle" fill="#aaa" font-size="10">${it.label}</text>`;
        if (opts.showValue !== false) {
          rects += `<text x="${x + (bw - 8) / 2}" y="${y - 4}" text-anchor="middle" fill="#ddd" font-size="10">${it.vText || it.v}</text>`;
        }
      });
      return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}" style="max-width:100%">${rects}</svg>`;
    }
    function svgLineChart(points, opts) {
      opts = opts || {};
      const w = opts.width || 520, h = opts.height || 180, pad = 28;
      if (points.length < 2) return '<p style="opacity:.6">样本不足</p>';
      const maxV = Math.max(...points.map(p => p.v), 1);
      const minV = Math.min(...points.map(p => p.v), 0);
      const span = Math.max(0.05, maxV - minV);
      const coords = points.map((p, i) => {
        const x = pad + (i * (w - pad * 2)) / (points.length - 1);
        const y = h - pad - ((p.v - minV) / span) * (h - pad * 2);
        return [x, y];
      });
      const d = coords.map((c, i) => (i ? 'L' : 'M') + c[0] + ',' + c[1]).join(' ');
      return `<svg viewBox="0 0 ${w} ${h}" width="100%" height="${h}" style="max-width:100%">
        <path d="${d}" fill="none" stroke="#81b64c" stroke-width="2.5" stroke-linecap="round"/>
        ${coords.map(c => `<circle cx="${c[0]}" cy="${c[1]}" r="3" fill="#95c95c"/>`).join('')}
      </svg>`;
    }
    function renderCharts(data) {
      if (!data) return;
      const games = (data.filtered || []).slice().sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
      const trendPts = [];
      let w = 0, d = 0, n = 0;
      const step = Math.max(1, Math.floor(games.length / 12));
      games.forEach((g, i) => {
        n++;
        if (g.result === 'win') w++;
        else if (g.result === 'draw') d++;
        if ((i + 1) % step === 0 || i === games.length - 1) {
          trendPts.push({ v: scoreOf(w, d, n) * 100 });
        }
      });
      const trendEl = document.getElementById('chartScoreTrend');
      if (trendEl) trendEl.innerHTML = svgLineChart(trendPts);

      const top = (data.openings || []).slice(0, 8);
      const distEl = document.getElementById('chartOpeningDist');
      if (distEl) {
        distEl.innerHTML = svgBarChart(top.map(o => ({
          label: (o.zh || '').slice(0, 4),
          v: o.games,
          vText: o.games,
          color: o.score < 0.42 ? '#e74c3c' : o.score > 0.55 ? '#81b64c' : '#eab308'
        })));
      }
      const ov = data.overview;
      const wSc = ov.whiteGames ? scoreOf(ov.whiteWins, ov.whiteDraws, ov.whiteGames) * 100 : 0;
      const bSc = ov.blackGames ? scoreOf(ov.blackWins, ov.blackDraws, ov.blackGames) * 100 : 0;
      const cc = document.getElementById('chartColorCompare');
      if (cc) {
        cc.innerHTML = svgBarChart([
          { label: '白棋', v: wSc, vText: wSc.toFixed(0) + '%', color: '#f5f5f4' },
          { label: '黑棋', v: bSc, vText: bSc.toFixed(0) + '%', color: '#78716c' }
        ], { height: 140 });
      }
    }

    async function fetchOpeningExplorer(opts) {
      // 优先 FEN，其次 play（逗号分隔 UCI）。多源回退。
      const fen = opts.fen || '';
      const play = opts.play || '';
      const sources = [];
      if (fen) {
        sources.push('https://explorer.lichess.cloud/masters?fen=' + encodeURIComponent(fen) + '&moves=12');
        sources.push('https://explorer.lichess.cloud/lichess?variant=standard&speeds=blitz,rapid,classical&ratings=1600,1800,2000,2200,2500&fen=' + encodeURIComponent(fen) + '&moves=12');
      }
      if (play) {
        sources.push('https://explorer.lichess.cloud/masters?play=' + encodeURIComponent(play));
        sources.push('https://explorer.lichess.cloud/lichess?variant=standard&speeds=blitz,rapid,classical&ratings=1600,1800,2000,2200,2500&play=' + encodeURIComponent(play));
      }
      let lastErr = null;
      for (const url of sources) {
        try {
          const ctrl = new AbortController();
          const timer = setTimeout(() => ctrl.abort(), 8000);
          const res = await fetch(url, {
            method: 'GET',
            mode: 'cors',
            credentials: 'omit',
            signal: ctrl.signal,
            headers: { Accept: 'application/json' }
          });
          clearTimeout(timer);
          if (!res.ok) { lastErr = new Error('HTTP ' + res.status); continue; }
          const data = await res.json();
          if (data && Array.isArray(data.moves)) return { data, url };
        } catch (e) {
          lastErr = e;
        }
      }
      throw lastErr || new Error('explorer unavailable');
    }
    function renderBookMovesHtml(title, moves, sourceNote) {
      const total = moves.reduce((s, m) => s + (m.white + m.draws + m.black), 0) || 1;
      return '<strong>' + title + '</strong>' +
        (sourceNote ? '<div class="hint-text" style="margin:4px 0 8px">' + sourceNote + '</div>' : '') +
        '<div class="theory-cont-list" style="margin-top:8px">' +
        moves.slice(0, 8).map(m => {
          const n = (m.white || 0) + (m.draws || 0) + (m.black || 0);
          const wr = n ? (((m.white || 0) + (m.draws || 0) * 0.5) / n * 100).toFixed(0) : '0';
          return `<div class="theory-cont-item" style="cursor:default">
            <div><strong style="color:var(--text-bright)">${m.san || m.uci || '?'}</strong>
            <div class="eco">${n} 局 · 白方得分率约 ${wr}% · 占比 ${(n / total * 100).toFixed(0)}%</div></div>
          </div>`;
        }).join('') + '</div>';
    }
    function selfBookForOpeningGames(games, prefixLen) {
      prefixLen = prefixLen || 6;
      // 用用户自己的对局统计该开局后续着法（不依赖外网）
      const map = {};
      let samplePrefix = [];
      for (const g of games) {
        const { sans, ucis } = (typeof gameMoveList === 'function') ? gameMoveList(g) : { sans: [], ucis: [] };
        if (!sans.length) continue;
        if (!samplePrefix.length && sans.length >= 2) samplePrefix = sans.slice(0, Math.min(prefixLen, sans.length));
        const next = sans[Math.min(prefixLen, sans.length - 1)];
        // 取第 prefixLen 步之后的一步作为「续着」：用前缀对齐
        if (sans.length <= 2) continue;
        // 统计从开局出发的第 3～8 步常见着（简化：统计整局中出现频率最高的早期着法）
        for (let i = 2; i < Math.min(sans.length, 8); i++) {
          const san = sans[i];
          if (!map[san]) map[san] = { san, white: 0, draws: 0, black: 0 };
          if (g.result === 'win') map[san].white++;
          else if (g.result === 'draw') map[san].draws++;
          else map[san].black++;
        }
      }
      return Object.values(map).sort((a, b) =>
        (b.white + b.draws + b.black) - (a.white + a.draws + a.black)
      ).slice(0, 8);
    }
