    // ---- 交互式训练：点格走子 ----
    function trainSqFromEvent(ev) {
      const board = document.getElementById('trainBoard');
      if (!board || !trainState || !trainState.chess) return null;
      const rect = board.getBoundingClientRect();
      const x = (ev.clientX - rect.left) / rect.width;
      const y = (ev.clientY - rect.top) / rect.height;
      if (x < 0 || y < 0 || x > 1 || y > 1) return null;
      const file = Math.min(7, Math.max(0, Math.floor(x * 8)));
      const rank = 7 - Math.min(7, Math.max(0, Math.floor(y * 8)));
      return 'abcdefgh'[file] + (rank + 1);
    }
    function onTrainBoardClick(ev) {
      if (!trainState || trainState.answered) return;
      const sq = trainSqFromEvent(ev);
      if (!sq) return;
      const chess = trainState.chess;
      if (!trainSelectedSq) {
        const piece = chess.get(sq);
        if (!piece || piece.color !== chess.turn()) return;
        trainSelectedSq = sq;
        renderTrainBoard(chess);
        // 高亮选中格：简单重绘后加 outline 不方便，用 status 提示
        document.getElementById('trainAnswer').textContent = '已选 ' + sq + '，再点目标格走子';
        return;
      }
      const from = trainSelectedSq;
      trainSelectedSq = null;
      let moved = null;
      try {
        moved = chess.move({ from: from, to: sq, promotion: 'q' });
      } catch (_) {}
      if (!moved) {
        document.getElementById('trainAnswer').textContent = '非法走法，请重试（先点己方棋子再点目标）';
        renderTrainBoard(chess);
        return;
      }
      trainState.userSan = moved.san;
      trainState.answered = true;
      renderTrainBoard(chess);
      const ok = moved.san.replace(/[+#]/g, '') === String(trainState.nextSan || '').replace(/[+#]/g, '');
      document.getElementById('trainAnswer').textContent =
        (ok ? '✓ 与你当时走法一致：' : '你走了 ' + moved.san + '，当时走的是 ') + trainState.nextSan +
        '（可打开完整分析看引擎）';
    }
    // 覆盖 startTrainRound 的棋盘渲染后绑定
    const _origStartTrain = typeof startTrainRound === 'function' ? startTrainRound : null;
    // 重新绑定训练按钮逻辑增强
    document.getElementById('trainBoard')?.addEventListener('click', onTrainBoardClick);

    const _btnStart = document.getElementById('btnStartTrain');
    const _btnNext = document.getElementById('btnNextTrain');
    function enhanceTrainStateAfterStart() {
      // trainState 在 startTrainRound 里设置；补 chess 引用
      setTimeout(() => {
        if (!trainState || !trainState.moves) return;
        try {
          ensureChess();
          const chess = new (getChessCtor())();
          for (let i = 0; i < trainState.ply; i++) chess.move(trainState.moves[i]);
          trainState.chess = chess;
          trainState.answered = false;
          trainState.userSan = '';
          trainSelectedSq = null;
          document.getElementById('trainAnswer').textContent = '点己方棋子，再点目标格走子；或点「揭晓原着」';
        } catch (e) { console.warn(e); }
      }, 30);
    }
    _btnStart?.addEventListener('click', enhanceTrainStateAfterStart);
    _btnNext?.addEventListener('click', enhanceTrainStateAfterStart);

    // ---- 批量准确率 ----
    async function runBatchAccuracy() {
      if (!lastAnalysisData) {
        setStatus('请先完成一次分析', 'error');
        return;
      }
      const status = document.getElementById('batchAccStatus');
      const summary = document.getElementById('batchAccSummary');
      const table = document.getElementById('batchAccTable');
      const weakNames = new Set((lastAnalysisData.weak || []).map(w => w.zh));
      let pool = (lastAnalysisData.filtered || []).filter(g =>
        g.result === 'loss' && (weakNames.has(g.opening.zh) || weakNames.size === 0)
      );
      if (pool.length < 3) pool = (lastAnalysisData.filtered || []).filter(g => g.result === 'loss');
      pool = pool.slice(0, 8);
      if (!pool.length) {
        if (status) status.textContent = '没有可分析的负局';
        return;
      }
      if (status) status.textContent = '准备引擎…';
      try {
        await loadAnnotateEngine();
      } catch (e) {
        if (status) status.textContent = '引擎不可用，请联网后重试';
        return;
      }
      const buckets = {
        '开局(1-10回合)': { n: 0, bad: 0, bl: 0, gap: 0 },
        '中局(11-25)': { n: 0, bad: 0, bl: 0, gap: 0 },
        '残局(26+)': { n: 0, bad: 0, bl: 0, gap: 0 }
      };
      for (let gi = 0; gi < pool.length; gi++) {
        if (status) status.textContent = '分析对局 ' + (gi + 1) + '/' + pool.length;
        const g = pool[gi];
        let moves = [];
        try {
          const parsed = parseMovesFromGame(g);
          moves = parsed.moves || [];
        } catch (_) { continue; }
        // 抽样最多 12 步关键节点
        const sampleIdx = [];
        for (let i = 4; i < moves.length && sampleIdx.length < 12; i += Math.max(1, Math.floor(moves.length / 12))) {
          sampleIdx.push(i);
        }
        const chess = new (getChessCtor())();
        for (let i = 0; i < moves.length; i++) {
          const fen = chess.fen();
          const mv = moves[i];
          if (sampleIdx.includes(i)) {
            const playedUci = (mv.from || '') + (mv.to || '') + (mv.promotion ? String(mv.promotion)[0] : '');
            const r = await engineEvalCp(fen, 0, 160);
            let gap = 40;
            if (r && r.multipv && r.multipv[0] && typeof r.multipv[0].cpSide === 'number') {
              const best = r.multipv[0];
              const found = r.multipv.find(line => line.uci && line.uci.slice(0, 4) === playedUci.slice(0, 4));
              if (found && typeof found.cpSide === 'number') gap = Math.max(0, best.cpSide - found.cpSide);
              else gap = 90;
            }
            const moveNo = Math.floor(i / 2) + 1;
            const key = moveNo <= 10 ? '开局(1-10回合)' : moveNo <= 25 ? '中局(11-25)' : '残局(26+)';
            const b = buckets[key];
            b.n++;
            b.gap += gap;
            if (gap >= 90) b.bad++;
            if (gap >= 280) b.bl++;
          }
          try { chess.move(mv); } catch (_) { break; }
        }
      }
      if (table) {
        table.innerHTML = Object.keys(buckets).map(k => {
          const b = buckets[k];
          const avg = b.n ? (b.gap / b.n).toFixed(0) : '—';
          return `<tr><td>${k}</td><td>${b.n}</td><td>${b.bad}</td><td>${b.bl}</td><td>${avg} cp</td></tr>`;
        }).join('');
      }
      if (summary) {
        const totalBad = Object.values(buckets).reduce((s, b) => s + b.bad, 0);
        const totalN = Object.values(buckets).reduce((s, b) => s + b.n, 0);
        summary.innerHTML = `<p>抽样 ${pool.length} 局 · ${totalN} 个关键节点 · 失误级着法 ${totalBad} 次。
          可在「训练」针对弱势开局中局多练。</p>`;
      }
      if (status) status.textContent = '完成';
    }
    document.getElementById('btnBatchAccuracy')?.addEventListener('click', () => {
      document.querySelectorAll('#resultTabs .tab-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.tab === 'tab-accuracy');
      });
      document.querySelectorAll('.results-main .tab-panel').forEach(p => {
        p.classList.toggle('hidden', p.id !== 'tab-accuracy');
      });
      runBatchAccuracy();
    });
    document.getElementById('btnRunBatchAccuracy')?.addEventListener('click', runBatchAccuracy);

    // ---- 分享报告页 ----
    function buildReportHtml(data) {
      const ov = data.overview;
      const sc = scoreOf(ov.wins, ov.draws, ov.total);
      let html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>开局分析报告</title>
        <style>body{font-family:system-ui,sans-serif;max-width:720px;margin:24px auto;padding:0 16px;color:#222}
        h1{font-size:1.4rem} table{border-collapse:collapse;width:100%} td,th{border:1px solid #ddd;padding:8px;text-align:left}
        .muted{color:#666;font-size:.9rem}</style></head><body>`;
      html += `<h1>开局弱点分析报告</h1>`;
      html += `<p class="muted">${new Date().toLocaleString()} · ${ov.total} 局 · 得分率 ${(sc*100).toFixed(1)}% · 胜/和/负 ${ov.wins}/${ov.draws}/${ov.losses}</p>`;
      html += `<h2>弱势开局</h2><ul>`;
      (data.weak || []).slice(0, 8).forEach(w => {
        html += `<li><strong>${w.zh}</strong> ${w.games}局 · ${(w.score*100).toFixed(0)}%</li>`;
      });
      if (!(data.weak || []).length) html += '<li>无明显弱势</li>';
      html += `</ul><h2>建议</h2><ul>`;
      generateTips(ov, data.weak || [], data.openings || [], data.trends || []).forEach(t => {
        html += `<li>${t}</li>`;
      });
      html += `</ul><p class="muted">由「开局弱点分析 + 鳕鱼引擎」生成</p></body></html>`;
      return html;
    }
    document.getElementById('btnShareReport')?.addEventListener('click', () => {
      if (!lastAnalysisData) { setStatus('请先分析', 'error'); return; }
      reportHtmlCache = buildReportHtml(lastAnalysisData);
      const prev = document.getElementById('reportPreview');
      if (prev) prev.innerHTML = reportHtmlCache.replace(/<!DOCTYPE[\s\S]*?<body>/, '').replace(/<\/body><\/html>/, '');
      document.getElementById('reportModal')?.classList.remove('hidden');
    });
