    function renderGbGamesList() {
      const tbody = document.getElementById('gbGamesBody');
      if (!tbody) return;
      const q = (document.getElementById('gbSearch')?.value || '').trim().toLowerCase();
      const rf = document.getElementById('gbResultFilter')?.value || 'all';
      let list = gbGames.map((g, idx) => ({ g, idx }));
      if (rf !== 'all') list = list.filter(x => x.g.result === rf);
      if (q) {
        list = list.filter(x => {
          const g = x.g;
          return (g.opponent || '').toLowerCase().includes(q) ||
            (g.opening && (g.opening.zh || '') || '').toLowerCase().includes(q) ||
            (g.opening && (g.opening.eco || '') || '').toLowerCase().includes(q);
        });
      }
      list.sort((a, b) => (b.g.createdAt || 0) - (a.g.createdAt || 0));
      if (!list.length) {
        tbody.innerHTML = '<tr><td colspan="7" style="opacity:.55;text-align:center;padding:20px">' +
          (gbGames.length ? '无匹配对局' : '拉取对局或粘贴 PGN 后显示列表') + '</td></tr>';
        return;
      }
      tbody.innerHTML = list.slice(0, 150).map(({ g, idx }) => {
        const resText = g.result === 'win' ? '胜' : g.result === 'draw' ? '和' : g.result === 'loss' ? '负' : '?';
        const resColor = g.result === 'win' ? 'var(--success)' : g.result === 'loss' ? 'var(--danger)' : 'var(--warning)';
        const timeStr = g.createdAt ? new Date(g.createdAt).toLocaleDateString() : '';
        const tc = (typeof timeControlLabel === 'function') ? timeControlLabel(g.timeControl) : (g.timeControl || '');
        return '<tr>' +
          '<td><span class="color-tag ' + (g.isWhite ? 'white' : 'black') + '"></span>' + (g.isWhite ? '白' : '黑') + '</td>' +
          '<td>' + (g.opponent || '—') + '</td>' +
          '<td>' + (g.oppRating != null ? g.oppRating : '—') + '</td>' +
          '<td style="color:' + resColor + ';font-weight:600">' + resText + '</td>' +
          '<td><span class="opening-name">' + (g.opening && g.opening.zh ? g.opening.zh : '—') + '</span>' +
            (g.opening && g.opening.eco ? '<span class="eco">' + g.opening.eco + '</span>' : '') + '</td>' +
          '<td>' + tc + (timeStr ? '<span class="eco">' + timeStr + '</span>' : '') + '</td>' +
          '<td><button type="button" class="btn btn-sm" data-gb-open="' + idx + '">分析</button>' +
            (g.url ? ' <a href="' + g.url + '" target="_blank" rel="noopener" style="color:var(--accent);font-size:.8rem;margin-left:4px">原站</a>' : '') +
          '</td></tr>';
      }).join('');
    }

    async function gbOpenAnalysis(idx) {
      const g = gbGames[idx];
      if (!g) return;
      // 保证 openAnalysis 能从 storedGames 取到
      let si = storedGames.indexOf(g);
      if (si < 0) {
        // 按 id 找
        si = storedGames.findIndex(x => x && g.id && x.id === g.id);
      }
      if (si < 0) {
        storedGames.push(g);
        si = storedGames.length - 1;
      } else {
        storedGames[si] = g;
      }
      closeGameBrowser();
      try {
        await window.openAnalysis(si);
      } catch (e) {
        alert('打开分析失败：' + (e && e.message ? e.message : e));
      }
    }

    async function gbFetchGames() {
      const username = (document.getElementById('gbUsername')?.value || '').trim();
      if (!username) {
        gbSetStatus('请输入用户名', true);
        return;
      }
      const max = Math.min(100, Math.max(1, parseInt(document.getElementById('gbMaxGames')?.value, 10) || 30));
      const color = document.getElementById('gbColor')?.value || 'all';
      const btn = document.getElementById('gbFetchBtn');
      if (btn) btn.disabled = true;
      gbSetStatus('正在从 ' + (gbPlatform === 'chesscom' ? 'Chess.com' : 'Lichess') + ' 拉取「' + username + '」最近 ' + max + ' 局…');
      try {
        let games = [];
        if (gbPlatform === 'chesscom') {
          games = await fetchChessComGames(username, max, ['all'], color);
        } else {
          games = await fetchLichessGames(username, max, ['all'], color);
        }
        if (!games.length) {
          gbSetStatus('未找到符合条件的对局', true);
          gbGames = [];
          renderGbGamesList();
          return;
        }
        gbGames = games;
        // 同步到主列表，便于复盘清单等
        storedGames = games.slice();
        renderGbGamesList();
        gbSetStatus('已加载 ' + games.length + ' 局 · 点击「分析」进入棋盘（引擎/角标/探索）');
        // 顺带写入主界面用户名
        const mu = document.getElementById('username');
        if (mu && !mu.value) mu.value = username;
      } catch (e) {
        console.warn(e);
        gbSetStatus('拉取失败：' + (e && e.message ? e.message : e), true);
      } finally {
        if (btn) btn.disabled = false;
      }
    }

    async function gbLoadPgn() {
      const text = document.getElementById('gbPgnInput')?.value || '';
      if (!String(text).trim()) {
        gbSetStatus('请先粘贴 PGN', true);
        return;
      }
      try {
        await ensureChessLib();
        ensureChess();
      } catch (e) {
        gbSetStatus('棋盘库未就绪：' + (e && e.message ? e.message : e), true);
        return;
      }
      const parts = splitPgnGames(text);
      const parsed = [];
      for (let i = 0; i < parts.length; i++) {
        const g = parseImportedPgnGame(parts[i], i);
        if (g) parsed.push(g);
      }
      if (!parsed.length) {
        gbSetStatus('无法解析 PGN（请检查格式）', true);
        return;
      }
      gbGames = parsed.concat(gbGames);
      // 合并进 storedGames
      parsed.forEach(g => {
        if (!storedGames.some(x => x.id === g.id)) storedGames.push(g);
      });
      renderGbGamesList();
      gbSetStatus('已解析 ' + parsed.length + ' 局 PGN · 点击「分析」打开');
    }

