    // ---- 开局详情：主线偏离点 ----
    const _openOpeningDetailOrig = openOpeningDetail;
    openOpeningDetail = function(zh) {
      _openOpeningDetailOrig(zh);
      setTimeout(async () => {
        const box = document.getElementById('bookBox');
        if (!box || !lastAnalysisData) return;
        const games = (lastAnalysisData.filtered || []).filter(g => (g.opening && g.opening.zh) === zh);
        // 找一局有足够着法的
        let sample = null, ucis = [];
        for (const g of games) {
          const ml = typeof gameMoveList === 'function' ? gameMoveList(g) : { ucis: [] };
          if (ml.ucis && ml.ucis.length >= 6) { sample = g; ucis = ml.ucis; break; }
        }
        if (!sample || !ucis.length) return;
        try {
          // 逐步查库，找第一次用户着法不在 top3 的步
          let play = [];
          let deviatePly = -1;
          let bookSan = '';
          let userSan = '';
          for (let i = 0; i < Math.min(ucis.length, 12); i++) {
            const fenChess = new (getChessCtor())();
            for (const u of play) {
              fenChess.move({ from: u.slice(0, 2), to: u.slice(2, 4), promotion: u[4] || 'q' });
            }
            const fen = fenChess.fen();
            let data = null;
            try {
              const r = await fetchOpeningExplorer({ fen, play: play.join(',') });
              data = r.data;
            } catch (_) { break; }
            const moves = (data && data.moves) || [];
            if (!moves.length) break;
            const top = moves.slice(0, 3).map(m => (m.uci || '').slice(0, 4));
            const userU = (ucis[i] || '').slice(0, 4);
            const topSan = moves[0] && moves[0].san;
            // user san
            let uSan = '';
            try {
              const t = new (getChessCtor())(fen);
              const m = t.move({ from: userU.slice(0, 2), to: userU.slice(2, 4), promotion: (ucis[i] || '')[4] || 'q' });
              if (m) uSan = m.san;
            } catch (_) {}
            if (userU && top.length && !top.includes(userU)) {
              deviatePly = i;
              bookSan = topSan || '';
              userSan = uSan;
              break;
            }
            play.push(ucis[i].slice(0, 4));
          }
          if (deviatePly >= 0) {
            const note = document.createElement('div');
            note.className = 'hint-text';
            note.style.marginTop = '10px';
            note.innerHTML = `<strong style="color:var(--warning)">偏离主线</strong>：约第 ${Math.floor(deviatePly / 2) + 1} 回合你走了 <strong>${userSan || '?'}</strong>，库中常见为 <strong>${bookSan || '?'}</strong>。`;
            box.appendChild(note);
          } else if (play.length >= 4) {
            const note = document.createElement('div');
            note.className = 'hint-text';
            note.style.marginTop = '10px';
            note.textContent = '前 ' + play.length + ' 步基本处于常见理论范围内。';
            box.appendChild(note);
          }
        } catch (e) { console.warn('deviate', e); }
      }, 600);
    };

